insert into ponew values
(1, 1, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Concentration of Lidocaine used for spinal anaesthesia is', '["0.25%", "0.2%", "5%", "2%"]'::jsonb, 2, 'Lidocaine for spinal anaesthesia is typically used at a higher concentration, around 5%, in hyperbaric preparations.', 'NAP 423 · General Anaesthesia I'),
(1, 2, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Diffusion hypoxia at the end of a nitrous oxide anaesthetic is prevented by:', '["Giving IV naloxone at the end of surgery to reverse the opioids", "Increasing the N₂O to 80%", "Giving 100% oxygen for a few minutes after stopping N₂O", "Turning off all gases at once"]'::jsonb, 2, 'N₂O floods into the alveoli and dilutes oxygen.', 'NAP 423 · General Anaesthesia I'),
(1, 3, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient in the ICU develops signs of urinary retention postoperatively. What intervention should the nurse implement?', '["Insert a urinary catheter", "Encourage increased fluid intake", "Initiate physical therapy", "Administer stool softeners"]'::jsonb, 0, 'Bladder catheterisation drains the retained urine when a patient cannot void, relieving bladder distension.', 'NAP 423 · General Anaesthesia I'),
(1, 4, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient who received suxamethonium remains paralysed for over an hour. The most likely cause is:', '["Opioid overdose from fentanyl", "Plasma cholinesterase deficiency", "Local anaesthetic systemic toxicity", "Malignant hyperthermia crisis"]'::jsonb, 1, 'Suxamethonium is broken down by plasma cholinesterase. Inherited or acquired deficiency prolongs apnoea (''scoline apnoea''). Management is continued sedation and ventilation until recovery.', 'NAP 423 · General Anaesthesia I'),
(1, 5, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient develops a wound infection postoperatively. What is the priority nursing intervention for managing a wound infection?', '["Administering antibiotics as prescribed", "Irrigating the wound with normal saline", "Changing the dressing daily", "Applying a warm compress to the wound"]'::jsonb, 0, 'Antibiotic therapy targeted at the causative organism is the priority intervention for a diagnosed wound infection.', 'NAP 423 · General Anaesthesia I'),
(1, 6, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Sevoflurane is preferred for inhalational (gas) induction because it is:', '["Very pungent and causes coughing", "Explosive in oxygen, so it is safer to give by mask", "Non-pungent and does not irritate the airway", "Given only intravenously"]'::jsonb, 2, 'Desflurane is pungent and unsuitable for gas induction.', 'NAP 423 · General Anaesthesia I'),
(1, 7, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A commonly used first-line antiemetic for postoperative nausea and vomiting prophylaxis is:', '["Ondansetron", "Succinylcholine", "Atropine", "Morphine"]'::jsonb, 0, 'Ondansetron, a 5-HT3 receptor antagonist, is a standard first-line agent for prevention and treatment of postoperative nausea and vomiting.', 'NAP 423 · General Anaesthesia I'),
(1, 8, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Standard preoperative fasting guidance for clear fluids before elective surgery is:', '["2 hours", "No restriction needed", "6 hours", "12 hours"]'::jsonb, 0, 'Clear fluids may be taken up to 2 hours before elective surgery under modern fasting guidelines, reducing unnecessary dehydration without increasing aspiration risk.', 'NAP 423 · General Anaesthesia I'),
(1, 9, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'The volatile agent with the highest MAC (lowest potency) of these is:', '["Isoflurane (about 1.15%)", "Desflurane (about 6%)", "Halothane (about 0.75%)", "Sevoflurane (about 2%)"]'::jsonb, 1, 'Higher MAC means lower potency.', 'NAP 423 · General Anaesthesia I'),
(1, 10, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Thiopentone is absolutely contraindicated in:', '["Epilepsy", "Raised intracranial pressure", "Acute porphyria", "Day-case surgery"]'::jsonb, 2, 'Barbiturates can trigger a porphyric crisis.', 'NAP 423 · General Anaesthesia I'),
(1, 11, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A recognised risk of prolonged mechanical ventilation is:', '["Guaranteed prevention of atelectasis", "Elimination of the need for sedation", "Improved spontaneous respiratory drive over time", "Ventilator-associated pneumonia (VAP)"]'::jsonb, 3, 'Prolonged mechanical ventilation increases the risk of ventilator-associated pneumonia, among other complications like barotrauma and diaphragmatic weakness.', 'NAP 423 · General Anaesthesia I'),
(1, 12, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Laryngoscope is best used for one of the following', '["Ventilation", "Visualization of esophagus", "Intubation", "Insertion of Nasogastric tube"]'::jsonb, 2, 'The laryngoscope is used to lift the tongue/epiglottis and expose the vocal cords for endotracheal tube placement.', 'NAP 423 · General Anaesthesia I'),
(1, 13, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient is at risk for developing post-operative sepsis. What nursing interventions can help prevent sepsis in the post-operative period?', '["Ensure proper hand hygiene and sterile technique during wound care", "Monitor vital signs for signs of infection, such as fever or tachycardia", "Administer antibiotics as prescribed to treat infections promptly", "Educate the patient on signs and symptoms of infection to report immediately"]'::jsonb, 1, 'Close vital sign monitoring for fever or tachycardia allows early recognition of developing postoperative sepsis.', 'NAP 423 · General Anaesthesia I'),
(1, 14, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient is at risk for developing post-operative respiratory complications. What nursing interventions can help prevent respiratory complications in the post-operative period?', '["Limit the patient''s fluid intake to prevent pulmonary edema", "Encourage deep breathing and coughing exercises", "Encourage the patient to lie flat in bed", "Administer oxygen as ordered"]'::jsonb, 1, 'Deep breathing and coughing exercises help clear secretions and re-expand the lungs, preventing postoperative respiratory complications.', 'NAP 423 · General Anaesthesia I'),
(1, 15, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Etomidate is useful in shocked patients because of cardiovascular stability, but it can cause:', '["Raised intracranial pressure", "Severe bronchospasm", "Adrenal suppression", "Malignant hyperthermia"]'::jsonb, 2, 'It inhibits cortisol synthesis.', 'NAP 423 · General Anaesthesia I'),
(1, 16, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient is at risk for developing blood clots postoperatively. Which intervention is essential to prevent this complication?', '["Administering blood thinners as prescribed", "Encouraging bedrest and immobilization", "Increasing salt intake", "Applying warm compress to the affected area"]'::jsonb, 0, 'Prophylactic anticoagulants (blood thinners) reduce the risk of venous thromboembolism in patients at risk for postoperative blood clots.', 'NAP 423 · General Anaesthesia I'),
(1, 17, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Which inhalational agent has the lowest blood–gas solubility coefficient?', '["Sevoflurane", "Nitrous oxide", "Desflurane", "Isoflurane"]'::jsonb, 2, 'Desflurane has the lowest blood–gas partition coefficient (about 0.42) of these agents, so its onset and offset are fastest.', 'NAP 423 · General Anaesthesia I'),
(1, 18, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Which group of patients is classically at highest risk of Mendelson''s syndrome?', '["Well-controlled type 2 diabetics undergoing outpatient dental extraction", "Patients undergoing local anaesthesia for minor skin procedures", "Patients who fasted appropriately before elective day-case surgery", "Pregnant women undergoing emergency general anaesthesia"]'::jsonb, 3, 'Pregnant women have delayed gastric emptying, reduced lower oesophageal sphincter tone, and raised intra-abdominal pressure, making them classically the highest-risk group for aspiration under general anaesthesia.', 'NAP 423 · General Anaesthesia I'),
(1, 19, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'The specific drug for malignant hyperthermia is:', '["Flumazenil", "Dantrolene", "Naloxone", "Neostigmine"]'::jsonb, 1, 'Dantrolene reduces calcium release from the sarcoplasmic reticulum. Initial dose is 2.5 mg/kg IV, repeated as needed. Triggers are stopped, the patient is cooled and hyperkalaemia and acidosis are treated.', 'NAP 423 · General Anaesthesia I'),
(1, 20, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'An anaesthetic agent contraindicated in hypertensive patients is:', '["Diazepam", "Ketamine", "Propofol", "Thiopentone sodium"]'::jsonb, 1, 'Ketamine stimulates the sympathetic nervous system, raising BP and heart rate, so avoid it in uncontrolled hypertension.', 'NAP 423 · General Anaesthesia I'),
(1, 21, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'The suffix ''E'' in an ASA classification (e.g. ASA II E) means:', '["The surgery is an emergency", "The patient has epilepsy", "The patient is elderly", "The patient is an organ donor"]'::jsonb, 0, 'Emergency surgery carries higher risk at any ASA level.', 'NAP 423 · General Anaesthesia I'),
(1, 22, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient on prophylactic LMWH (e.g. enoxaparin) should usually have neuraxial block no sooner than:', '["12 hours after the last dose", "2 hours after the last dose", "30 minutes after the last dose", "7 days after the last dose"]'::jsonb, 0, 'Treatment doses need about 24 hours, to reduce epidural haematoma risk.', 'NAP 423 · General Anaesthesia I'),
(1, 23, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'The Jackson-Rees (Mapleson F) breathing system is mainly used for:', '["Elderly adults only", "Obstetric spinal anaesthesia", "Long-term ICU ventilation", "Children"]'::jsonb, 3, 'It has low resistance and a bag that shows spontaneous breathing.', 'NAP 423 · General Anaesthesia I'),
(1, 24, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient is at risk for developing post-operative nausea and vomiting (PONV). What nursing interventions can help prevent PONV in the post-operative period?', '["Administer antiemetic medications as prescribed", "Avoid administering opioids for pain management", "Encourage the patient to drink clear liquids", "Monitor the patient''s intake and output closely"]'::jsonb, 0, 'Antiemetic medication is the standard intervention to prevent and manage postoperative nausea and vomiting (PONV).', 'NAP 423 · General Anaesthesia I'),
(1, 25, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient recovering from anaesthesia after a lung transplant requires particular nursing vigilance for:', '["Only cardiac monitoring, with no respiratory focus", "Bowel function exclusively", "Skin integrity exclusively", "Signs of rejection and pulmonary infection"]'::jsonb, 3, 'Post-transplant patients need close monitoring for graft rejection and infection, alongside standard post-anaesthetic respiratory and haemodynamic care.', 'NAP 423 · General Anaesthesia I'),
(1, 26, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A renal transplant recipient on tacrolimus is at particular risk of:', '["Hypercoagulability from a strong immune system", "Increased antibody production and allergy", "Weight loss and persistent hypotension", "Infection, nephrotoxicity and hyperglycaemia"]'::jsonb, 3, 'Drug levels are monitored; interactions with antifungals and antibiotics are common.', 'NAP 423 · General Anaesthesia I'),
(1, 27, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient in the ICU is on mechanical ventilation. What nursing interventions are important to maintain ventilator function and prevent complications?', '["Limiting suctioning to prevent infection", "Disconnecting the patient from the ventilator periodically for breaks", "Monitoring ventilator settings and alarms regularly", "Administering sedatives to keep the patient calm"]'::jsonb, 2, 'Regular monitoring of ventilator settings and alarms helps detect and correct problems (e.g. disconnection, high pressures) before they harm the patient.', 'NAP 423 · General Anaesthesia I'),
(1, 28, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A comprehensive nutritional assessment typically integrates which four broad components?', '["Blood pressure, pulse, respiratory rate and core temperature", "Anthropometry, biochemistry, clinical examination and dietary history", "Body weight and height only, used to calculate the BMI", "Vital signs, medication list, allergy history and resuscitation status"]'::jsonb, 1, 'The classic ''ABCD'' framework of nutritional assessment includes Anthropometric measurements, Biochemical/laboratory data, Clinical examination, and Dietary history, providing a comprehensive picture of nutritional status.', 'NAP 423 · General Anaesthesia I'),
(1, 29, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'What action should be taken in preparation for potential organ injury postoperatively in the ICU?', '["Applying warm compresses", "Encouraging coughing and deep breathing", "Monitoring lab values", "Administering pain medication"]'::jsonb, 2, 'Monitoring relevant laboratory values (e.g. renal function tests) allows early detection of postoperative organ injury.', 'NAP 423 · General Anaesthesia I'),
(1, 30, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient in the ICU is at risk for developing a pressure ulcer postoperatively. What nursing interventions can help prevent this complication?', '["Repositioning the patient every 2 hours", "Massaging bony prominences", "Applying direct pressure to areas at risk", "Keeping the head of the bed elevated"]'::jsonb, 0, 'Repositioning at least every 2 hours relieves sustained pressure over bony prominences, reducing pressure ulcer risk.', 'NAP 423 · General Anaesthesia I'),
(1, 31, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Sugammadex reverses neuromuscular blockade caused by:', '["Suxamethonium", "Rocuronium and vecuronium", "Atracurium and cisatracurium only", "Fentanyl and morphine"]'::jsonb, 1, 'Sugammadex encapsulates the steroidal blockers rocuronium and vecuronium, giving rapid reversal even from deep block. It has no effect on suxamethonium or benzylisoquinoliniums.', 'NAP 423 · General Anaesthesia I'),
(1, 32, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A nurse is caring for a sedated patient. The nurse should be aware that the patient is at risk for which of the following?', '["Pressure ulcers and skin breakdown", "An increased level of consciousness", "A decrease in length of stay in the ICU", "Decreased risk of aspiration"]'::jsonb, 0, 'A sedated patient has a decreased level of consciousness and may be immobile for prolonged periods. This makes them highly susceptible to pressure ulcers and skin breakdown. The nurse must perform frequent repositioning and skin assessments.', 'NAP 423 · General Anaesthesia I'),
(1, 33, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Correct Flowmeter rate with Nonrebreathing mask is', '["21 -25", "16 -20", "10 -15", "5 -9"]'::jsonb, 3, 'A non-rebreathing mask requires a flow rate of roughly 5-9 (up to about 10-15) L/min to keep the reservoir bag inflated and deliver a high FiO2.', 'NAP 423 · General Anaesthesia I'),
(1, 34, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A patient is at risk for developing post-operative ileus. What nursing interventions can help prevent or manage post-operative ileus?', '["Administer laxatives as ordered", "Encourage the patient to avoid consuming fluids", "Apply heat to the abdomen to promote bowel motility", "Encourage early ambulation and activity"]'::jsonb, 3, 'Early ambulation and activity stimulate bowel motility, helping prevent or resolve postoperative ileus.', 'NAP 423 · General Anaesthesia I'),
(1, 35, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'A normal end-tidal CO₂ in a ventilated healthy adult is about:', '["5–10 mmHg (0.7–1.3 kPa)", "0 mmHg", "80–100 mmHg (10–13 kPa)", "35–45 mmHg (4.5–6 kPa)"]'::jsonb, 3, 'No trace means the tube is not in the trachea or there is no cardiac output.', 'NAP 423 · General Anaesthesia I'),
(1, 36, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'The preferred muscle relaxant in a patient with liver or renal failure is:', '["Pancuronium", "Atracurium", "Rocuronium", "Vecuronium"]'::jsonb, 1, 'Atracurium (and cisatracurium) is broken down by Hofmann elimination and ester hydrolysis, without needing the liver or kidneys.', 'NAP 423 · General Anaesthesia I'),
(1, 37, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'The nerve most commonly stimulated to monitor neuromuscular blockade is the:', '["Median", "Ulnar", "Facial", "Radial"]'::jsonb, 1, 'Train-of-four monitoring usually stimulates the ulnar nerve and watches the adductor pollicis (thumb).', 'NAP 423 · General Anaesthesia I'),
(1, 38, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'An epidural test dose (e.g. lidocaine with adrenaline) is given to detect:', '["The patient''s pain threshold", "Intravascular or intrathecal catheter placement", "Correct catheter length inside the epidural space", "Allergy to chlorhexidine"]'::jsonb, 1, 'Tachycardia suggests intravascular; rapid dense block suggests intrathecal.', 'NAP 423 · General Anaesthesia I'),
(1, 39, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'What intervention is crucial in preventing organ injury or damage postoperatively?', '["Administering antibiotics", "Monitoring vital signs", "Encouraging coughing and deep breathing", "Providing pain management"]'::jsonb, 1, 'Close vital sign and haemodynamic monitoring helps detect early signs of organ hypoperfusion or injury before it becomes severe.', 'NAP 423 · General Anaesthesia I'),
(1, 40, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 423 · General Anaesthesia I', 'Which statement about xenon anaesthesia is NOT true?', '["It has minimal cardiovascular side effects", "It is non-explosive", "It has low blood–gas solubility", "It gives slow induction and slow recovery"]'::jsonb, 3, 'Xenon is non-explosive, has very low blood–gas solubility (FAST induction and recovery) and minimal cardiovascular effects. It is limited by cost.', 'NAP 423 · General Anaesthesia I'),
(1, 41, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Hypnotic drugs, as a pharmacological class, are primarily used to:', '["Increase heart rate", "Reverse anticoagulation", "Induce and maintain sleep", "Treat hypertension"]'::jsonb, 2, 'Hypnotics are a class of drugs used specifically to induce and/or maintain sleep.', 'NAP 421 · Applied Pharmacology II'),
(1, 42, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'What is the first-line antidote for suspected opioid overdose causing respiratory depression?', '["N-acetylcysteine", "Flumazenil", "Naloxone", "Atropine"]'::jsonb, 2, 'Naloxone is a competitive opioid receptor antagonist that rapidly reverses opioid-induced respiratory and CNS depression.', 'NAP 421 · Applied Pharmacology II'),
(1, 43, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Morphine should be used with care in renal failure because:', '["It raises the serum potassium sharply", "It is not metabolised at all by the liver", "It causes direct kidney stones", "Its active metabolite morphine-6-glucuronide accumulates"]'::jsonb, 3, 'Accumulation causes prolonged sedation and respiratory depression.', 'NAP 421 · Applied Pharmacology II'),
(1, 44, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'A patient develops serotonin syndrome after being started on two serotonergic medications simultaneously. The nurse should recognise this presentation includes:', '["Agitation, hyperthermia, tremor, and autonomic instability", "Bradycardia and hypotension with no other findings", "Improved mental status", "No clinical significance requiring only observation"]'::jsonb, 0, 'Serotonin syndrome presents with agitation, hyperthermia, neuromuscular abnormalities (tremor, clonus) and autonomic instability, requiring prompt recognition and discontinuation of the causative agents.', 'NAP 421 · Applied Pharmacology II'),
(1, 45, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'A patient on IV nitroglycerin has a headache. Which action is BEST?', '["Administer PRN acetaminophen", "Switch to oral nitrates", "Increase the infusion rate", "Hold the next dose"]'::jsonb, 0, 'Headache is a common side effect of nitrates. Acetaminophen is appropriate; tolerance develops over time.', 'NAP 421 · Applied Pharmacology II'),
(1, 46, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'An older adult client with a history of blood clots is in the emergency room with suspected deep vein thrombosis (DVT) of the left leg. The critical care nurse starts IV heparin as ordered. Which of the following is LEAST likely to be included in the care plan?', '["Analgesics as ordered", "Ambulation as tolerated", "Warm, moist soaks applied to the affected area", "Anti-embolism stockings"]'::jsonb, 1, 'Warm, moist soaks are avoided in active DVT as heat plus massage-like handling can dislodge a clot.', 'NAP 421 · Applied Pharmacology II'),
(1, 47, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Adrenaline for adult anaphylaxis is given first-line as:', '["0.5 mg (0.5 mL of 1:1000) IM", "0.5 mg of 1:1000 by IV push", "1 mg orally as a tablet", "5 mg IV bolus over 1 minute"]'::jsonb, 0, 'IM adrenaline into the anterolateral thigh is repeated after 5 minutes if needed. IV adrenaline is given only by experienced staff with monitoring, in diluted small titrated doses.', 'NAP 421 · Applied Pharmacology II'),
(1, 48, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'A patient in septic shock requires norepinephrine. Which effect is PRIMARY for this drug?', '["Increased myocardial contractility", "Vasoconstriction", "Renal artery dilation", "Bronchodilation"]'::jsonb, 1, 'Norepinephrine is an α-agonist that increases SVR and MAP in septic shock. Inotropy is secondary.', 'NAP 421 · Applied Pharmacology II'),
(1, 49, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'One of the following is a muscle relaxant', '["Fortwin", "Midazolam", "Pentazocine", "Pethidine"]'::jsonb, 1, 'Midazolam (via its muscle-relaxant sedative properties) is grouped here as the muscle relaxant, unlike the opioids pentazocine, fortwin, and pethidine.', 'NAP 421 · Applied Pharmacology II'),
(1, 50, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'A patient is admitted to ICU with diagnosis of vaso-occlusive crisis, which of this management will you start with?', '["Transfuse with fresh whole blood", "Give oral rehydration solution", "Rehydrate with normal saline", "Order for narcotics and administer"]'::jsonb, 2, 'Aggressive rehydration with normal saline is the first step in managing vaso-occlusive crisis.', 'NAP 421 · Applied Pharmacology II'),
(1, 51, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Which of the following agents is most likely to cause airway irritation, coughing, and breath-holding, making it unsuitable for inhalational induction?', '["Desflurane", "Nitrous oxide", "Propofol", "Sevoflurane"]'::jsonb, 0, 'Desflurane is pungent and irritates the airway, commonly causing coughing, breath-holding, and laryngospasm if used for induction, so it is reserved for maintenance after the airway is secured.', 'NAP 421 · Applied Pharmacology II'),
(1, 52, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'A patient on dopamine at 15 mcg/kg/min is likely to experience:', '["Vasoconstriction", "Renal artery dilation", "Bronchospasm", "Hyperglycemia"]'::jsonb, 0, 'High-dose dopamine (>10 mcg/kg/min) activates α-receptors, causing vasoconstriction.', 'NAP 421 · Applied Pharmacology II'),
(1, 53, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Flumazenil, used to reverse benzodiazepine sedation, should be used cautiously in patients who:', '["Have never taken benzodiazepines", "Have normal renal function", "Are undergoing routine anaesthesia reversal only", "Are chronic benzodiazepine users, due to seizure risk"]'::jsonb, 3, 'In chronic benzodiazepine users, flumazenil can precipitate acute withdrawal and seizures by abruptly reversing tolerance-related GABA receptor effects.', 'NAP 421 · Applied Pharmacology II'),
(1, 54, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Clonidine as an adjunct in anaesthesia provides:', '["Neuromuscular reversal", "Bronchodilation only", "Muscle paralysis", "Sedation, analgesia and reduced sympathetic response"]'::jsonb, 3, 'Side effects include bradycardia and hypotension.', 'NAP 421 · Applied Pharmacology II'),
(1, 55, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'A recognised adverse effect of inotropic infusions (e.g. dobutamine) is:', '["Bradycardia", "Hypoglycaemia", "Reduced myocardial oxygen demand", "Tachyarrhythmias and myocardial ischaemia"]'::jsonb, 3, 'Inotropes such as dobutamine, dopamine and adrenaline raise contractility but can cause tachycardia, arrhythmias and myocardial ischaemia by increasing oxygen demand.', 'NAP 421 · Applied Pharmacology II'),
(1, 56, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Volatile anaesthetics relax the uterus, which is important because at caesarean section they may cause:', '["Faster delivery of the baby", "Fetal hyperglycaemia", "Uterine rupture before incision", "Increased bleeding from uterine atony at high concentrations"]'::jsonb, 3, 'Keep concentrations low after delivery and give uterotonics.', 'NAP 421 · Applied Pharmacology II'),
(1, 57, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'A patient with septic shock is started on vasopressin. Which effect is expected?', '["Increased urine output", "Coronary vasodilation", "Vasoconstriction", "Decreased SVR"]'::jsonb, 2, 'Vasopressin is a potent vasoconstrictor used in refractory septic shock.', 'NAP 421 · Applied Pharmacology II'),
(1, 58, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'A patient who has been admitted with a gastric ulcer now develops severe epigastric pain that spreads over the entire abdomen. He is very pale and is lying on his side. What should be the nurse''s immediate action?', '["Reposition the patient in Semi-Fowler''s Position.", "Notify the doctor and check the vitals.", "Perform deep palpations on the abdomen.", "Immediately administer opioids."]'::jsonb, 1, 'Sudden severe abdominal pain with pallor after a known ulcer suggests perforation — notify the doctor and check vitals immediately.', 'NAP 421 · Applied Pharmacology II'),
(1, 59, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Which action should the nurse take when preparing patient-controlled analgesia for a postoperative patient?', '["Instruct the patient to administer a dose only when experiencing pain.", "Ask another nurse to double-check the setup before patient use.", "Provide clear, simple instructions for dosing if the patient is cognitively impaired", "Caution the patient to limit the number of times he presses the dosing button."]'::jsonb, 1, 'Having a second nurse double-check PCA setup is a core safety practice before patient use.', 'NAP 421 · Applied Pharmacology II'),
(1, 60, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Sevoflurane can react with dry soda lime to form:', '["Nitrogen gas", "Compound A and heat", "Carbon monoxide only", "Cyanide"]'::jsonb, 1, 'Desiccated absorbents are a fire and toxicity risk.', 'NAP 421 · Applied Pharmacology II'),
(1, 61, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Which history requires caution when giving paracetamol (acetaminophen)?', '["Allergy to aspirin", "Occasional alcohol use", "Gastric irritation with bleeding", "Hepatitis B"]'::jsonb, 3, 'Paracetamol is metabolised by the liver and is hepatotoxic. Use it with caution in liver disease such as hepatitis B.', 'NAP 421 · Applied Pharmacology II'),
(1, 62, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'The nurse is caring for a patient on a continuous sedative infusion. The nurse should be aware that which of the following is a major complication of prolonged sedation?', '["Delirium and an increased length of stay in the ICU", "A decreased need for mechanical ventilation", "An increased level of consciousness", "Increased mobility and decreased risk of pressure ulcers"]'::jsonb, 0, 'Prolonged sedation can lead to a number of negative consequences, including delirium, an increased length of stay, and an increased risk of long-term cognitive impairment. The goal is to use the least amount of sedation necessary to keep the patient comfortable and safe.', 'NAP 421 · Applied Pharmacology II'),
(1, 63, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'A patient on furosemide (a loop diuretic) should be monitored closely for which electrolyte disturbance?', '["Hyperkalaemia", "Hypercalcaemia only", "Hypokalaemia", "Hypernatraemia only"]'::jsonb, 2, 'Loop diuretics like furosemide promote potassium loss and commonly cause hypokalaemia, requiring regular electrolyte monitoring.', 'NAP 421 · Applied Pharmacology II'),
(1, 64, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Naloxone is administered to a patient in the Emergency room. This is an antidote for for which of the following type of poisoning?', '["Chlorine poisoning", "Tricyclic antidepressant use", "Opiate poisoning", "Alcohol overdose"]'::jsonb, 2, 'Naloxone is the specific opioid antagonist/antidote.', 'NAP 421 · Applied Pharmacology II'),
(1, 65, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Before giving morphine 4 mg IV for incisional pain, the nurse should:', '["Assess the patient''s respiratory status", "Monitor the heart rate only", "Assess the incision", "Clarify the order with the prescriber"]'::jsonb, 0, 'Opioids depress respiration, so check respiratory rate and sedation before giving IV morphine.', 'NAP 421 · Applied Pharmacology II'),
(1, 66, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'What is the antidote for a cholinergic crisis caused by anticholinesterase medication overdose?', '["Flumazenil", "Naloxone", "Atropine", "Protamine sulfate"]'::jsonb, 2, 'Atropine, an anticholinergic agent, is used to counteract the excessive muscarinic effects of a cholinergic crisis caused by anticholinesterase overdose.', 'NAP 421 · Applied Pharmacology II'),
(1, 67, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'During adult cardiac arrest, IV adrenaline (epinephrine) is administered at what dose and interval?', '["1mg every 15 minutes", "0.1mg every 1 minute", "1mg every 3–5 minutes", "10mg once only"]'::jsonb, 2, 'Standard ACLS dosing is 1mg IV adrenaline every 3–5 minutes during cardiac arrest resuscitation.', 'NAP 421 · Applied Pharmacology II'),
(1, 68, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'The critical care nurse follows the recommended protocol for preventing constipation when starting a patient on opioids by', '["Using a bowel stimulant and stool softener.", "Increasing fluids and exercise.", "Adding bulk fibre to the diet", "Giving the patient enemas as needed."]'::jsonb, 0, 'A bowel stimulant plus stool softener is the standard combination to prevent opioid-induced constipation.', 'NAP 421 · Applied Pharmacology II'),
(1, 69, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Oxytocin is given after delivery of the baby at caesarean section to:', '["Relax the uterus for delivery", "Suppress lactation after delivery", "Lower the maternal blood pressure", "Contract the uterus and reduce PPH"]'::jsonb, 3, 'Rapid IV bolus may cause hypotension and tachycardia; it is given slowly or as an infusion.', 'NAP 421 · Applied Pharmacology II'),
(1, 70, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Ondansetron''s main side effects include:', '["Hyperkalaemia", "Severe sedation and amnesia", "Extrapyramidal reactions and dystonia", "Headache, constipation and QT prolongation"]'::jsonb, 3, 'Metoclopramide is the antiemetic that causes extrapyramidal effects.', 'NAP 421 · Applied Pharmacology II'),
(1, 71, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'When administering furosemide, the nurse should closely monitor for:', '["Hypoglycaemia specifically caused by the drug", "Hypokalaemia and other electrolyte disturbances", "Hyperkalaemia", "Bradycardia as the primary risk"]'::jsonb, 1, 'Furosemide, a loop diuretic, promotes potassium (and other electrolyte) losses in the urine, making electrolyte monitoring essential during therapy.', 'NAP 421 · Applied Pharmacology II'),
(1, 72, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'When preparing patient-controlled analgesia (PCA) for a postoperative patient, the nurse should:', '["Tell the patient to limit button presses", "Ask another nurse to double-check the setup before use", "Give dosing instructions to a cognitively impaired patient", "Tell the patient to dose only when in severe pain"]'::jsonb, 1, 'PCA pumps are high-alert. An independent double-check of the drug, concentration and settings prevents fatal programming errors.', 'NAP 421 · Applied Pharmacology II'),
(1, 73, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'A nurse must give a 40 mg IV push dose over 4 minutes. The drug is supplied as 40 mg in 4 mL. At what rate, in mL/min, should the nurse push the medication?', '["1 mL/min", "0.5 mL/min", "10 mL/min", "4 mL/min"]'::jsonb, 0, 'Concentration = 40 mg/4 mL = 10 mg/mL. To deliver 40 mg over 4 minutes = 10 mg/min = 1 mL/min.', 'NAP 421 · Applied Pharmacology II'),
(1, 74, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'Before elective surgery, aspirin given for secondary heart prevention is usually:', '["Always stopped 4 weeks before", "Replaced with warfarin", "Continued, unless the surgeon advises otherwise", "Doubled on the day of surgery"]'::jsonb, 2, 'Stopping it risks coronary events; clopidogrel is often stopped 7 days before.', 'NAP 421 · Applied Pharmacology II'),
(1, 75, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 421 · Applied Pharmacology II', 'A patient on heparin has platelets falling by more than 50% with new thrombosis. The nurse expects to:', '["Increase the heparin dose to treat the new clot", "Stop all heparin, including flushes, and start a non-heparin anticoagulant", "Switch to low molecular weight heparin injections", "Give a platelet transfusion and keep the heparin"]'::jsonb, 1, 'Heparin-induced thrombocytopenia causes clots, not bleeding. Argatroban or fondaparinux are alternatives.', 'NAP 421 · Applied Pharmacology II'),
(1, 76, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'How many pulmonary veins empty into the right atrium?', '["One", "None", "Four", "Two"]'::jsonb, 1, 'The four pulmonary veins drain oxygenated blood into the LEFT atrium. None enter the right atrium.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 77, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Endocrine glands differ from exocrine glands in that endocrine glands:', '["Always secrete through a duct onto an epithelial surface", "Only function during childhood", "Never produce chemical messengers", "Secrete hormones directly into the bloodstream, with no ducts"]'::jsonb, 3, 'Endocrine glands are ductless — they release hormones directly into the bloodstream, unlike exocrine glands which secrete via ducts.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 78, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The volume of air remaining in the lungs at the end of a normal, quiet expiration is the:', '["Vital capacity", "Tidal volume", "Functional residual capacity", "Residual volume"]'::jsonb, 2, 'FRC = residual volume + expiratory reserve volume. It is the oxygen reservoir between breaths; it falls with anaesthesia, obesity, supine and head-down positions.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 79, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Serum is blood plasma minus its:', '["Sodium ions", "Calcium ions", "Albumin", "Fibrinogen"]'::jsonb, 3, 'Serum is plasma with the clotting proteins, chiefly fibrinogen, removed.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 80, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Which of these is a granulocyte?', '["A lymphocyte", "A macrophage", "An erythrocyte", "An eosinophil"]'::jsonb, 3, 'Granulocytes are neutrophils, eosinophils and basophils. Lymphocytes and monocytes/macrophages are agranulocytes.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 81, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The nervous system can inhibit or stimulate other systems in order to maintain:', '["Integration", "Mental balance", "Homeostasis", "Growth"]'::jsonb, 2, 'By stimulating or inhibiting other systems, the nervous system helps maintain homeostasis.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 82, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The urinary bladder''s primary anatomical function is to:', '["Reabsorb electrolytes", "Produce urine", "Filter blood", "Store urine until voiding"]'::jsonb, 3, 'The bladder is a muscular reservoir that stores urine produced by the kidneys until it is voided through the urethra.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 83, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Most of the body cells'' energy is derived from chemical reactions, which can only take place in the presence of:', '["Carbon dioxide", "Oxygen", "ATP", "Blood"]'::jsonb, 1, 'Aerobic metabolism (oxidative phosphorylation) needs oxygen and produces most of the cell''s ATP.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 84, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The common bile duct is formed by the union of the:', '["Cystic duct and the common hepatic duct", "Pancreatic duct and the cystic duct", "Common hepatic duct and the pancreatic duct", "Right and left hepatic ducts"]'::jsonb, 0, 'The right and left hepatic ducts join to form the common hepatic duct, which joins the cystic duct to form the common bile duct. It joins the pancreatic duct at the ampulla of Vater.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 85, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'A patient with hypochloremia (Cl⁻ 88 mEq/L) and metabolic alkalosis should receive:', '["Ammonium chloride", "Potassium supplements", "0.45% saline IV", "Acetazolamide"]'::jsonb, 2, 'Hypochloremic metabolic alkalosis (e.g., from vomiting) responds to chloride-rich fluids (e.g., 0.9% or 0.45% saline).', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 86, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The heart''s four chambers consist of:', '["Four atria only", "One atrium and three ventricles", "Two atria and two ventricles", "Four ventricles only"]'::jsonb, 2, 'The heart has two upper chambers (right and left atria) and two lower chambers (right and left ventricles).', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 87, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Heparin and histamine are secreted by:', '["B lymphocytes", "Neutrophils", "Plasma cells", "Basophils"]'::jsonb, 3, 'Basophils, like mast cells, secrete heparin and histamine.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 88, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The layer of the heart responsible for its pumping contraction is the:', '["Myocardium", "Endocardium", "Epicardium", "Pericardium"]'::jsonb, 0, 'The myocardium is the thick muscular middle layer responsible for the heart''s contractile pumping action.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 89, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The correct order of the stages of fracture (bone) healing is:', '["Granulation, remodelling, haematoma, consolidation, callus", "Callus, haematoma, granulation, remodelling, consolidation", "Remodelling, haematoma, granulation, callus, consolidation", "Haematoma, granulation, callus, consolidation, remodelling"]'::jsonb, 3, 'Bleeding forms a haematoma, which is replaced by granulation tissue, then soft and hard callus. Woven bone consolidates into lamellar bone and is remodelled over months.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 90, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Absorption of digested nutrients occurs primarily in the:', '["Small intestine", "Large intestine", "Stomach", "Oesophagus"]'::jsonb, 0, 'The small intestine, with its large surface area from villi and microvilli, is the primary site of nutrient absorption.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 91, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Which change shifts the oxyhaemoglobin dissociation curve to the RIGHT (so oxygen is released more readily to tissues)?', '["Hypothermia, alkalosis and a low PaCO₂", "Low PaCO₂ with low red-cell 2,3-DPG", "Raised temperature, PaCO₂, acidity and 2,3-DPG", "Carbon monoxide and fetal haemoglobin"]'::jsonb, 2, 'Active, hot, acidic tissues favour oxygen release (Bohr effect). Hypothermia, alkalosis, carbon monoxide, fetal haemoglobin and low 2,3-DPG shift the curve to the left.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 92, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Which cranial nerve is the motor nerve to the tongue muscles?', '["Hypoglossal nerve", "Glossopharyngeal nerve", "Oculomotor nerve", "Olfactory nerve"]'::jsonb, 0, 'The hypoglossal nerve (CN XII) is the motor nerve to the tongue muscles.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 93, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Total lung capacity is best defined as:', '["The maximum volume of air the lungs can hold after maximal inspiration", "The volume remaining in the lungs after maximal expiration", "The volume of air moved in a single normal breath", "The volume exhaled in the first second of forced expiration"]'::jsonb, 0, 'Total lung capacity is the maximum volume of air the lungs can contain after a maximal inspiratory effort.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 94, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'A nurse is caring for a post- CABG patient. While performing hemodynamic monitoring, he noted that Pulmonary Artery pressure is 31/18. The nurse would understand which of the following abnormality as the cause of the this PA pressure reading:', '["Pulmonary valve stenosis", "Pulmonary infection", "Left side heart failure", "Right sided heart failure"]'::jsonb, 2, 'Elevated pulmonary artery pressures often reflect back-pressure transmitted from a failing left heart.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 95, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The brain structure primarily responsible for coordinating balance and fine motor movement is the:', '["Medulla oblongata", "Cerebrum", "Thalamus", "Cerebellum"]'::jsonb, 3, 'The cerebellum coordinates balance, posture, and the fine-tuning of voluntary motor movements.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 96, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'ABG: pH 7.48, PaCO₂ 48 mmHg, HCO₃⁻ 35 mmol/L indicates:', '["Metabolic alkalosis with respiratory compensation", "Metabolic acidosis with respiratory compensation", "Respiratory acidosis with metabolic compensation", "Acute respiratory alkalosis from hyperventilation"]'::jsonb, 0, 'Causes include vomiting, NG suction and diuretics.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 97, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'McBurney''s point, the usual site of maximum tenderness in appendicitis, lies:', '["At the tip of the ninth costal cartilage", "Two-thirds of the way from the umbilicus to the left anterior superior iliac spine", "One-third of the way from the right anterior superior iliac spine to the umbilicus", "Midway between the umbilicus and the pubic symphysis"]'::jsonb, 2, 'McBurney''s point is on the line from the right ASIS to the umbilicus, one-third of the way from the ASIS. The gridiron (McBurney) incision for open appendicectomy is made here.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 98, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'Hormonal control of a target organ commonly occurs through:', '["Direct nerve stimulation only, with no chemical signal", "Hormones binding to specific receptors on or in target cells", "Muscle contraction alone", "Physical contact between glands and organs"]'::jsonb, 1, 'Hormones exert their effects by binding to specific receptors on or within target cells, triggering a physiological response.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 99, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'The part of the CNS housed within the cranial vault is the:', '["Brainstem only", "Medulla oblongata only", "Spinal cord", "Brain"]'::jsonb, 3, 'The brain lies within the cranial vault. The spinal cord lies in the vertebral canal.', 'NAP 430 · Applied Anatomy & Physiology II'),
(1, 100, 'Anaesthesia Nursing Mock — Day 6 Morning (Nov 2026)', 'NAP 430 · Applied Anatomy & Physiology II', 'During cholecystectomy, Calot''s triangle is identified because it contains the:', '["Portal vein; bounded by the pancreas, duodenum and the stomach", "Cystic artery; bounded by cystic duct, common hepatic duct and liver", "Hepatic artery proper; bounded by the stomach and the duodenum", "Common bile duct; bounded by the gallbladder fundus and liver"]'::jsonb, 1, 'Clearly displaying Calot''s triangle (the ''critical view of safety'') before clipping the cystic duct and artery prevents injury to the common bile duct.', 'NAP 430 · Applied Anatomy & Physiology II'),
(2, 1, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'To prevent TRALI, blood banks:', '["Use leukocyte-reduced blood", "Irradiate blood products", "Avoid plasma from multiparous donors", "Wash RBCs"]'::jsonb, 2, 'TRALI is often caused by donor antibodies; deferral of multiparous women reduces risk.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 2, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'A patient with IgA deficiency is at risk for:', '["TACO", "TRALI", "Febrile reaction", "Anaphylactic reaction"]'::jsonb, 3, 'IgA-deficient patients may develop anti-IgA antibodies, causing anaphylaxis.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 3, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'A prolonged INR in a patient not on warfarin suggests:', '["Low haemoglobin only", "Normal clotting", "Liver disease or vitamin K deficiency", "Excess platelets"]'::jsonb, 2, 'Correct before surgery or neuraxial block.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 4, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Troponin is considered a highly specific biomarker for:', '["Renal injury", "Hepatic injury", "Myocardial injury", "Pancreatic injury"]'::jsonb, 2, 'Cardiac troponin (I or T) is released specifically from injured cardiac myocytes, making it a highly sensitive and specific biomarker for myocardial injury.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 5, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'FFP is thawed and must be infused within:', '["24 hours", "6 hours", "4 hours", "30 minutes"]'::jsonb, 0, 'Thawed FFP is stable for 24 hours at 1-6°C.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 6, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'The commonest pathogens in Nigerian ICUs include:', '["Only respiratory viruses such as influenza", "Klebsiella, Pseudomonas, S. aureus, Acinetobacter", "Only fungi such as Candida and Aspergillus", "Only parasites such as malaria and worms"]'::jsonb, 1, 'Resistance is common; culture and sensitivity guide therapy.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 7, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'A patient has fever, chills, and hypotension during transfusion. The nurse suspects:', '["TRALI", "TACO", "Febrile non-hemolytic reaction", "Acute hemolytic reaction"]'::jsonb, 0, 'TRALI presents with acute respiratory distress, fever, and hypotension.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 8, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Transfusion-associated circulatory overload (TACO) is treated with:', '["Give more blood quickly to finish", "Lie the patient completely flat", "Start broad-spectrum antibiotics", "Stop, sit up, give oxygen and diuretics"]'::jsonb, 3, 'Elderly and cardiac patients are at higher risk.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 9, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'To reduce contamination risk, blood cultures should ideally be drawn:', '["Without skin antisepsis", "From two separate sites, ideally before starting antibiotics", "From a single site only, after antibiotics are given", "Only from a central line hub"]'::jsonb, 1, 'Drawing cultures from two separate peripheral sites with proper skin antisepsis, ideally before antibiotic administration, improves diagnostic yield and reduces contamination and false negatives.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 10, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Blood for grouping and cross-matching should be collected before giving which plasma expander?', '["Dextran", "Mannitol", "Haemaccel", "Hydroxyethyl starch"]'::jsonb, 0, 'Dextran coats red cells and causes rouleaux, which interferes with grouping and cross-matching. Take the cross-match sample before giving it.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 11, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Which blood cells are destroyed in a delayed haemolytic transfusion reaction?', '["Platelets", "White blood cells", "Red blood cells", "Plasma cells"]'::jsonb, 2, 'A delayed haemolytic transfusion reaction is immune destruction of the transfused red cells (RBCs) days after transfusion, usually from an anamnestic antibody response.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 12, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Which laboratory result would the nurse expect in DIC?', '["A decreased prothrombin time (PT)", "A low fibrinogen level", "An increased white cell count", "An increased platelet count"]'::jsonb, 1, 'DIC consumes fibrinogen and platelets, so fibrinogen is low, platelets are low, PT/aPTT are prolonged and D-dimer is raised.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 13, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Which patient can safely receive AB-negative blood?', '["A-negative", "O-negative", "B-negative", "AB-negative"]'::jsonb, 3, 'AB-negative red cells carry A and B antigens, so of these recipients only an AB-negative patient can receive them safely.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 14, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Protein-calorie malnutrition in ICU leads to:', '["Faster recovery from the critical illness", "Weight gain only, with no harmful effects", "Better immunity against hospital infections", "Poor healing, infection and weak breathing muscles"]'::jsonb, 3, 'Early nutrition reduces complications.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 15, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Which of these genotypes is most susceptible to severe malaria?', '["SS", "AA (normal homozygote)", "AS (sickle-cell trait)", "SC"]'::jsonb, 1, 'People with normal haemoglobin (HbAA) lack the partial protection against severe falciparum malaria that sickle trait (HbAS) gives.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 16, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Albumin is low in critical illness mainly because of:', '["Inflammation and capillary leak", "Dehydration and diuretics", "Overfeeding with enteral feeds", "Excess dietary intake"]'::jsonb, 0, 'Albumin is a poor nutritional marker in ICU.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 17, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'A client is receiving a blood transfusion. The critical care nurse observes that the client is experiencing diarrhoea, abdominal pain, and chills. Which of the following actions should the nurse take FIRST?', '["Stop the transfusion.", "Administer meperidine.", "Get a warming blanket.", "Assist the client to the bathroom."]'::jsonb, 0, 'Diarrhoea, pain, and chills during a transfusion signal a reaction — stopping the transfusion is the first priority action.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 18, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Heparin-induced thrombocytopenia (HIT) typically occurs:', '["Only after switching to oral warfarin", "Only with LMWH given to young children", "Within minutes of the first heparin dose", "5–10 days after starting heparin, with thrombosis"]'::jsonb, 3, 'Stop all heparin and use an alternative anticoagulant.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 19, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Each unit of blood should be completed within:', '["24 hours of leaving the fridge", "4 hours of leaving the fridge", "30 minutes of leaving the fridge", "12 hours of leaving the fridge"]'::jsonb, 1, 'Longer times increase bacterial growth.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 20, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Where are platelets formed?', '["In the kidneys", "In the liver", "In the blood vessels", "In the bone marrow"]'::jsonb, 3, 'Platelets come from megakaryocytes in the bone marrow.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 21, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'A patient with thrombocytopenia has oozing from IV sites. The nurse prepares to administer:', '["Platelets", "PRBCs", "FFP", "Cryoprecipitate"]'::jsonb, 0, 'Platelets treat thrombocytopenic bleeding.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 22, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'One unit of blood raises the haemoglobin concentration by about:', '["0.1 g/dL", "2 g/dL", "2.2 g/dL", "1 g/dL"]'::jsonb, 3, 'One unit of whole blood or packed red cells raises Hb by about 1 g/dL in an average adult.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 23, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Coagulopathy or low platelet count in a patient with GI bleeding:', '["Increases the risk of rebleeding", "Only matters in upper GI bleeds, not lower", "Has no bearing on bleeding risk", "Reduces the risk of rebleeding"]'::jsonb, 0, 'If the blood can''t clot effectively, any bleeding point is far more likely to continue or restart.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 24, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Which is true about haemophilia C?', '["It is due to factor IX deficiency", "It is due to factor XI deficiency", "It is due to factor VIII deficiency", "It is known as Christmas disease"]'::jsonb, 1, 'Haemophilia A is factor VIII deficiency, B (Christmas disease) is factor IX, and C is factor XI deficiency.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 25, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Which of the following pathogens is a common cause of ventilator-associated pneumonia (VAP) in the ICU?', '["Tapeworm", "Malaria parasite", "Pseudomonas aeruginosa", "Common cold rhinovirus only"]'::jsonb, 2, 'Pseudomonas aeruginosa is a common and often resistant pathogen implicated in ventilator-associated pneumonia in ICU patients.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 26, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Microcytic anaemia (low MCV) is classically associated with:', '["Acute haemorrhage only", "Folate deficiency", "Vitamin B12 deficiency", "Iron deficiency"]'::jsonb, 3, 'Iron deficiency anaemia is the classic cause of microcytic (small red cell) anaemia, whereas B12/folate deficiency typically causes macrocytic anaemia.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 27, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'A full blood count (FBC) primarily provides information about:', '["Liver enzyme levels only", "Red cells, white cells, and platelets", "Blood clotting time exclusively", "Blood glucose levels"]'::jsonb, 1, 'A full blood count measures red blood cell, white blood cell and platelet parameters, providing a broad picture of haematological status.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 28, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Which of the following common ICU-acquired pathogens is a fungal organism (rather than bacterial)?', '["Pseudomonas aeruginosa", "Candida species", "MRSA", "Klebsiella pneumoniae"]'::jsonb, 1, 'Candida species are fungal organisms and a recognised cause of ICU-acquired infections, particularly in patients with central lines or broad-spectrum antibiotic exposure.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 29, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'The immediate haemostatic response to a damaged vessel is:', '["Vasoconstriction", "Platelet adhesion", "Platelet aggregation", "Viscous metamorphosis of platelets"]'::jsonb, 0, 'The first response to vessel injury is reflex vasoconstriction, followed by platelet adhesion, aggregation and coagulation.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 30, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 422 · Chemical Pathology & Haematology', 'Culture and sensitivity results guide:', '["Antibiotic choice and de-escalation", "The choice of IV maintenance fluid", "Sedation dosing in ventilated patients", "Blood group selection for transfusion"]'::jsonb, 0, 'Empirical therapy is changed once results return.', 'NAP 422 · Chemical Pathology & Haematology'),
(2, 31, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', '16 second, and QRS complexes measure 0.06 second. The overall heart rate is 64 beats per minute. The nurse assesses the cardiac rhythm as:', '["Normal sinus rhythm", "Sinus bradycardia", "First-degree heart block", "Sick sinus syndrome"]'::jsonb, 0, 'Normal PR/QRS intervals with a rate of 64 (within normal range) describe normal sinus rhythm.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 32, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A 70 kg man after a crash has pulse 125, BP 95/70, RR 32, urine 10 mL/hour and is anxious and confused. Using the ATLS classes, his estimated blood loss is:', '["Class III, 1500–2000 mL (30–40%)", "Class IV, over 2000 mL (over 40%)", "Class II, 750–1500 mL (15–30%)", "Class I, under 750 mL (under 15%)"]'::jsonb, 0, 'Class III shows a falling systolic BP, tachycardia above 120, low urine output and confusion. It requires blood transfusion.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 33, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Acute adrenal (Addisonian) crisis is a life-threatening emergency best managed with immediate administration of which agent, alongside aggressive fluid resuscitation?', '["IV insulin", "IV levothyroxine", "IV hydrocortisone", "Oral fludrocortisone only"]'::jsonb, 2, 'Adrenal crisis requires immediate IV stress-dose hydrocortisone (which also has mineralocorticoid activity at high doses) plus aggressive isotonic saline and dextrose administration to correct hypotension and hypoglycemia; delay in treatment can be fatal.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 34, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Which of the following is a priority goal for the client with COPD?', '["Treating infectious agents.", "Maintaining functional ability.", "Increasing carbon dioxide levels in the blood.", "Minimizing chest pain."]'::jsonb, 1, 'Maintaining functional ability is a central, realistic priority goal in chronic COPD management.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 35, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A Patient with CKD has a low erythropoietin {EPO} level. The patient is at risk for?', '["Blood clots", "Hypercalcaemia", "Anaemia", "Hyperkalemia"]'::jsonb, 2, 'Low erythropoietin from failing kidneys leads to anaemia.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 36, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Which viral hepatitis is the most common viral cause of fulminant hepatic failure?', '["Hepatitis A", "Hepatitis B", "Hepatitis C", "Hepatitis E only"]'::jsonb, 1, 'Among the viral causes, hepatitis B is the most frequently implicated in fulminant liver failure.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 37, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Inotropes increase:', '["Systemic vascular resistance only", "Venous capacity", "Myocardial contractility", "Heart block"]'::jsonb, 2, 'Examples: dobutamine, milrinone, adrenaline.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 38, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A chest drain should not be clamped during transport because:', '["A tension pneumothorax may develop", "The fluid inside the tube will clot", "The drain is more likely to fall out", "It increases the risk of infection"]'::jsonb, 0, 'Keep the bottle below chest level instead.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 39, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Which is not the stage of shock?', '["Reversible", "Compensatory", "Initial", "Progressive"]'::jsonb, 0, 'The standard shock stages are initial, compensatory, progressive, and irreversible — "reversible" isn''t one of them.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 40, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A patient with severe cirrhosis of the liver develops hepatorenal syndrome. Which of the following nursing assessment data would support this?', '["Decreased urinary concentration", "Weight gain of less than 1kg per week", "Oliguria and azotemia", "Metabolic alkalosis"]'::jsonb, 2, 'Oliguria with rising nitrogenous waste (azotaemia) is the hallmark of hepatorenal syndrome.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 41, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A nurse is monitoring a patient''s oxygen saturation with a pulse oximeter. A reading of 92% is considered:', '["Mild hypoxemia", "Severe hypoxemia", "Normal", "A sign of hyperoxia"]'::jsonb, 0, 'A normal oxygen saturation is typically 95% or higher. A reading of 92% is considered mild hypoxemia and may require an increase in oxygen therapy or further assessment.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 42, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Drugs that are used in symptomatic bradycardia are......', '["Adrenaline and dobutamine", "Adrenaline and Dopamine", "Atropine and Dopamine", "Atropine and Adrenaline"]'::jsonb, 2, 'Atropine and dopamine are used to manage symptomatic bradycardia.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 43, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Severe refractory hypoxaemia in an asthma patient is classified as which type of intubation indication?', '["Contraindicated", "Delayed only", "Absolute", "Relative"]'::jsonb, 2, 'When oxygen levels cannot be corrected despite maximal treatment, this is an absolute indication requiring immediate intubation.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 44, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Torsades de pointes, a polymorphic ventricular tachycardia, is classically associated with:', '["Complete heart block only", "Normal QT interval in all cases", "A shortened QT interval", "A prolonged QT interval"]'::jsonb, 3, 'Torsades de pointes arises in the setting of a prolonged QT interval (congenital or drug-induced), and IV magnesium sulfate is a key treatment regardless of magnesium level.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 45, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A 50-year old man is admitted to the trauma resuscitation unit. He is intubated on arrival. What is the next step in the primary survey?', '["Assess the patient''s blood pressure and peripheral pulses.", "Initiate large-bore intravenous catheter placement and replace fluid.", "Obtain a chest x-ray to determine tube placement", "Listen to lung sounds to assess for ventilation."]'::jsonb, 3, 'After intubation, the immediate next step is confirming effective ventilation by auscultating breath sounds.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 46, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Tranexamic acid in major trauma is most effective when given:', '["After 8 hours of injury", "Within 3 hours of injury", "Only once the INR exceeds 3", "Only after surgery is completed"]'::jsonb, 1, 'The CRASH-2 trial showed benefit within 3 hours and possible harm after.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 47, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A 30-year-old man with a stab wound to the neck is alert but bleeding actively in the resuscitation bay. You should first:', '["Locally explore the wound to find the bleeding point", "Clamp the bleeding vessels blindly", "Apply direct pressure to the site", "Place two large-bore IV cannulae and give O-negative blood"]'::jsonb, 2, 'Control external haemorrhage from a neck wound with direct pressure. Never clamp blindly or probe the wound in the resuscitation bay; the patient needs surgical exploration.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 48, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Central venous catheters (CVCs)', '["CVCs inserted via a thoracic vein are not visible on the chest radiograph", "Smaller-calibre central catheters can also be peripherally inserted via antecubital veins.", "The subclavian, internal jugular, and femoral veins are the sites of venous access used most commonly;", "CVCs are used frequently in the ICU patient for venous access, monitoring central venous pressure, and haemodialysis."]'::jsonb, 0, 'CVCs inserted via any central vein, including thoracic veins, are visible on chest X-ray — the statement claiming otherwise is false.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 49, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A 40-year-old woman is involved in an equestrian accident. She presents with chest pain, shortness of breath, and difficulty breathing. Her arterial oxygen saturation is 85% and her respiratory rate is 40b/minute. A chest tube is placed and the nurse observes a return of 300 mls blood into the system. What is the nurse''s next line of action?', '["Call for a chest x-ray.", "Place the patient on oxygen.", "Clamp the tube and notify surgeon immediately.", "Explain to the patient what is going on to alley anxiety."]'::jsonb, 2, 'Sudden return of 300ml blood via the chest tube signals major haemorrhage — clamp and notify the surgeon immediately.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 50, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Hemodynamic monitoring consist of;', '["Invasive", "Non invasive", "None of above", "Both of them"]'::jsonb, 3, 'Hemodynamic monitoring includes both invasive (arterial/CVP/PAC) and non-invasive (BP cuff, ECG) methods.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 51, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Which of the following is not a treatment modality for patient with epiglottitis?', '["Steroids", "Tracheostomy", "Antibiotics", "Observation"]'::jsonb, 3, 'Simple observation alone is inadequate for epiglottitis, which is a true airway emergency requiring active intervention.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 52, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'The normal CVP range is:', '["0–2mmHg", "10–20mmHg", "2–8mmHg", "30–40mmHg"]'::jsonb, 2, 'This is the accepted normal range for pressure in the central veins, reflecting venous return to the right heart.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 53, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Which one of the following test is used to monitor a Diabetes Mellitus patient?', '["Fasting Blood Sugar", "Creatinine test", "Total protein", "Alkaline phosphatase"]'::jsonb, 0, 'Fasting blood sugar is the standard test used to monitor diabetes control.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 54, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'The patient has vomiting that is very similar to coffee grounds. Where can the location of the bleeding be?', '["Rectum", "Small Intestine", "Large Intestine (colon)", "Upper GI Tract"]'::jsonb, 3, 'Coffee-ground emesis reflects digested blood from an upper GI source.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 55, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Which of the following refers to blood in the pleural space?', '["Pneumothorax", "Pyothorax", "Pulmonary oedema", "Haemothorax"]'::jsonb, 3, 'Blood in the pleural space is haemothorax.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 56, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'The osmolality of the renal interstitium increases from the cortex toward the tip of the inner medulla, reaching approximately what value in a maximally concentrating human kidney?', '["About 600 mOsm/kg at the papilla", "About 1200 mOsm/kg", "About 300 mOsm/kg", "About 2500 mOsm/kg"]'::jsonb, 1, 'The interstitial osmolality rises from about 300 mOsm/kg in the cortex to as high as roughly 1200 mOsm/kg at the papillary tip of the inner medulla.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 57, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'A low CVP most commonly indicates:', '["Fluid overload", "Normal fluid status always", "Right heart failure", "Hypovolaemia"]'::jsonb, 3, 'When venous return is reduced due to inadequate circulating volume, CVP drops.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 58, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'In patients with normal cardiopulmonary status, increasing the ________ is the treatment of choice in improving the patient''s oxygenation.', '["FiO2", "PEEP", "VT", "PSV"]'::jsonb, 0, 'Increasing FiO2 is the first-line way to improve oxygenation in a patient with otherwise normal cardiopulmonary status.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 59, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'In a patient with pulmonary arterial hypertension, which factor most worsens pulmonary vascular resistance and must be avoided in the ICU?', '["Normothermia with adequate analgesia", "Mild hyperoxia with normocapnia", "A slightly alkalotic pH from mild hyperventilation", "Hypoxia, hypercapnia and acidosis"]'::jsonb, 3, 'Hypoxia, hypercarbia and acidosis cause pulmonary vasoconstriction. Oxygen, normocapnia and avoiding acidosis lower PVR.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 60, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'The hallmark of myocardial infarction on an ECG is the present of:', '["ST segment elevation", "Prolong QRS complex", "Shorten QRS complex", "ST segment deviation"]'::jsonb, 0, 'ST-segment elevation is the hallmark ECG finding of acute MI.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 61, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'As a nurse performing cardio-pulmonary resuscitation on a cardiac arrest patient, you are aware that the correct cardiac compression to optimised cardiac function is:', '["115 compressions per minute", "100 Compressions per minute", "110 compressions per minute", "120 Compressions per minute"]'::jsonb, 3, 'The recommended compression rate is about 120 compressions per minute (within the 100-120 range, closest to the given option).', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 62, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Symptoms associated with anaemia include', '["Moderate breathlessness", "Increased breathlessness", "Increased activity intolerance", "Decreased breathlessness"]'::jsonb, 1, 'Anaemia classically causes increased breathlessness due to reduced oxygen-carrying capacity.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 63, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'What is the main target of neuromuscular blockers?', '["Motor end plate", "Central nervous system (CNS)", "Muscle membrane", "Synoptic vesicles"]'::jsonb, 0, 'The motor end plate (neuromuscular junction) is the primary target of these drugs.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 64, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'Which of the following is NOT a reversible cause of Cardiac Arrest?', '["Hypoxia", "Tension pneumothorax", "Hypertension", "Hypovolemia"]'::jsonb, 2, 'Hypertension is not part of the reversible 4H/4T causes of arrest; the others (hypovolaemia, hypoxia, tension pneumothorax) are.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 65, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 424 · Resuscitation & Intensive Care', 'The following electrolyte is most found outside the cells .', '["Magnesium", "Potassium", "Bicarbonate", "Sodium"]'::jsonb, 3, 'Sodium is the predominant extracellular cation.', 'NAP 424 · Resuscitation & Intensive Care'),
(2, 66, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Most umbilical hernias in infants:', '["Close on their own by about 4–5 years", "Need emergency surgery", "Turn cancerous if they are not removed early", "Strangulate in the first week"]'::jsonb, 0, 'Surgery is offered if they persist or are large.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 67, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'The incubation period of Ebola virus disease is:', '["2 months", "1–2 hours", "1 year", "2–21 days"]'::jsonb, 3, 'Contacts are followed up for 21 days.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 68, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Phantom limb pain after amputation is:', '["Pain caused only by tight bandages", "Imagined pain that should be ignored", "A sign of stump infection only, needing antibiotics", "A real pain felt in the missing limb"]'::jsonb, 3, 'Treatments include neuropathic analgesics and mirror therapy.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 69, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'A woman with a uterine scar (previous caesarean) and severe abdominal pain with fetal heart abnormalities in labour suggests:', '["False labour", "Uterine rupture", "Urinary tract infection", "Normal labour pain"]'::jsonb, 1, 'Immediate laparotomy is needed.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 70, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'After an open inguinal hernia repair, the patient is advised to:', '["Stay on strict bed rest for 2 weeks", "Do sit-ups from the first day after surgery", "Avoid heavy lifting for about 4–6 weeks", "Avoid walking at all for about a month"]'::jsonb, 2, 'Early walking is encouraged; straining is avoided.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 71, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'The usual threshold for treating neonatal hypoglycaemia is blood glucose below:', '["5.5 mmol/L (about 100 mg/dL)", "1.0 mmol/L only if the baby has seizures", "2.6 mmol/L (about 45 mg/dL)", "8.0 mmol/L (about 145 mg/dL)"]'::jsonb, 2, 'Babies at risk include preterm, small or large babies and babies of diabetic mothers.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 72, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'The circulating blood volume of a term neonate is about:', '["20 mL/kg", "150 mL/kg", "40 mL/kg (half the adult volume)", "80–90 mL/kg"]'::jsonb, 3, 'A small absolute blood loss is significant in babies.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 73, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'A halo vest is used to:', '["Treat a fractured femur in adults", "Reduce ankle swelling after sprain", "Immobilise the cervical spine", "Support a broken wrist in children"]'::jsonb, 2, 'Keep the spanner for emergency removal attached to the vest.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 74, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'The most important post-operative observation after limb surgery is:', '["Regular neurovascular checks of the limb", "Daily weight on the ward scales", "Nail colour only, checked once a day on the ward round", "Hair growth on the operated limb"]'::jsonb, 0, 'Report pain out of proportion, pallor, coldness or numbness.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 75, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Painless frank haematuria in a smoker over 50 years should be investigated for:', '["Urinary tract infection only", "Bladder cancer", "Prostatitis", "Renal colic"]'::jsonb, 1, 'Investigations include cystoscopy and imaging of the upper tracts.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 76, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Pulmonary oedema in severe pre-eclampsia is worsened by:', '["Excessive IV fluids", "Fluid restriction", "Left lateral position", "Magnesium sulphate"]'::jsonb, 0, 'Fluids are restricted to about 80 mL/hour.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 77, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Which of the following is not an obstetric cause of disseminated intravascular coagulopathy;', '["Pre-eclampsia/eclampsia", "Amniotic fluid embolism", "Uterine inversion", "Abruptio placentae"]'::jsonb, 2, 'Obstetric causes of DIC include abruption, amniotic fluid embolism, pre-eclampsia/HELLP and sepsis. Uterine inversion causes haemorrhage and shock rather than DIC.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 78, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'A 16 year-old is admitted to the floor after a foot-ball injury. The patient has a femur fracture. An external fixation device was applied in the operating room. The patient is at an increased risk for development of which of the following complications:', '["Pressure sore.", "Post-traumatic stress disorder.", "Deep venous thrombosis.", "Pulmonary embolism."]'::jsonb, 2, 'Immobilisation with external fixation and long bone fracture markedly raises DVT risk.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 79, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Which one of these treatments of leukemia is still under investigation?', '["Immunotherapy", "Gene therapy", "Cord blood and placenta transplant", "Bone marrow transplant"]'::jsonb, 1, 'Gene therapy for leukaemia remains an area of ongoing investigation/research rather than standard established treatment.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 80, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'A child with suspected Lassa fever is admitted. The nurse''s first priority is:', '["Isolation only after results return", "Strict isolation with full PPE", "Admission to an open paediatric ward", "Relatives providing care freely at the bedside"]'::jsonb, 1, 'Health worker infection is common; sharps and body fluids are handled with extreme care.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 81, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Primary postpartum haemorrhage is defined as blood loss of:', '["100 mL or more within 24 h of vaginal birth", "500 mL or more within 24 h of vaginal birth", "50 mL or more within the first hour of birth", "500 mL or more between 6 and 12 weeks later"]'::jsonb, 1, 'For caesarean section, 1000 mL or more is often used. Secondary PPH occurs between 24 hours and 12 weeks.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 82, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'This describe the premature separation of a normally situated placenta occurring after the 28th week of pregnancy.', '["Placenta circumventer", "Abruption placentae", "Placenta praevia", "Placenta accrete"]'::jsonb, 1, 'Premature separation of a normally implanted placenta after 28 weeks is abruptio placentae.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 83, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Mal-rotation with volvulus can be diagnosed through the following EXCEPT:', '["Abdominal ultrasound", "ESR", "History taking", "Abdominal x-ray"]'::jsonb, 1, 'ESR (an inflammatory marker) doesn''t diagnose malrotation/volvulus, unlike imaging and history.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 84, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Placenta praevia classically presents with:', '["Bleeding that occurs only after the delivery", "Painful dark bleeding with a hard, tender uterus", "Sudden sharp abdominal pain without any bleeding", "Painless bright red bleeding in late pregnancy"]'::jsonb, 3, 'Digital vaginal examination is avoided until praevia is excluded. Placental abruption is painful with a woody hard uterus.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 85, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Urethroplasty is surgery to:', '["Fix the testis in the scrotum", "Repair a urethral stricture", "Remove the kidney", "Remove the bladder"]'::jsonb, 1, 'Catheter care is important after surgery.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 86, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Asymmetrical intra-uterine growth restriction is usually caused by:', '["Chromosomal abnormalities early in pregnancy", "Congenital infection in the first trimester", "Genetic small stature", "Placental insufficiency late in pregnancy"]'::jsonb, 3, 'Head growth is spared at the expense of the abdomen (''brain sparing'').', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 87, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Primary postpartum haemorrhage following a caesarean section is defined as blood loss of:', '["≥500ml", "≥250ml", "≥1000ml", "≥3000ml"]'::jsonb, 2, 'The threshold is higher after a C-section (1000ml) compared to a vaginal delivery (500ml), reflecting the naturally greater blood loss expected with surgery.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 88, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Which of the following is not a sign of acute appendicitis', '["Murphy''s sign", "Obturator sign", "Rovsing''s sign", "Pointing sign"]'::jsonb, 0, 'Murphy''s sign relates to gallbladder disease, not appendicitis.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 89, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Blood at the urethral meatus after pelvic fracture means the nurse should NOT:', '["Check the pelvis on an X-ray film before giving analgesia", "Give the patient analgesia for the pain", "Insert a urethral catheter before injury is excluded", "Record the vital signs every 15 minutes"]'::jsonb, 2, 'A retrograde urethrogram may be needed.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 90, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Pale stools and dark urine with prolonged jaundice in a 4-week-old baby suggest:', '["Biliary atresia (obstructive jaundice)", "Breast milk jaundice only", "Hypothyroidism only, needing thyroid hormone", "Normal physiological jaundice"]'::jsonb, 0, 'Urgent referral is needed.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 91, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'The most common presentation of a pre-eclamptic patient is:', '["Convulsions", "No symptoms", "Abdominal pain", "Dyspareunia"]'::jsonb, 1, 'Most women with pre-eclampsia have no symptoms. It is found by routine BP and urine checks, which is why antenatal screening matters.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 92, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Which statement about intussusception is FALSE?', '["It is mostly found in adolescents", "The proximal bowel telescopes into the distal bowel", "It usually occurs in healthy babies without a demonstrable cause", "It most commonly occurs at the ileocolic junction"]'::jsonb, 0, 'Intussusception is most common in infants of 6–18 months, usually ileocolic and often without a clear cause. It is not mainly an adolescent disease.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 93, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'A third-degree perineal tear involves the:', '["Rectal mucosa", "Skin of the perineum only", "Vaginal mucosa only", "Anal sphincter complex"]'::jsonb, 3, 'A fourth-degree tear also involves the rectal mucosa.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 94, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Urinary diversion by ileal conduit means:', '["Urine drains normally through the urethra after bladder removal", "Ureters drain into an ileal segment brought out as a stoma", "A catheter is left permanently in the urethra after cystectomy", "The bladder is reconstructed using a segment of the colon"]'::jsonb, 1, 'Mucus in urine is normal. The stoma should be pink and moist; urine output is monitored.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 95, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'In Ebola, health workers must remove PPE:', '["Quickly in any order", "In a set sequence with a trained observer", "In the patient''s room with the patient watching", "Without hand hygiene"]'::jsonb, 1, 'Most health worker infections occur during PPE removal.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 96, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'The main indication for exchange blood transfusion in a newborn is:', '["Uncomplicated prematurity below 34 weeks", "Mild physiological jaundice on day 3", "Severe jaundice despite intensive phototherapy", "Neonatal hypoglycaemia not responding to feeds"]'::jsonb, 2, 'It removes bilirubin and sensitised red cells (e.g. in Rh or ABO haemolytic disease) and corrects anaemia, preventing kernicterus.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 97, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Fluid maintenance for a 10 kg child using the Holliday-Segar method is:', '["1500 mL per 24 hours", "1000 mL per 24 hours", "2000 mL per 24 hours", "500 mL per 24 hours"]'::jsonb, 1, '100 mL/kg for the first 10 kg, 50 mL/kg for the next 10 kg, and 20 mL/kg for each kg above 20.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 98, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'When investigating a newborn with hyperbilirubinaemia, which bilirubin fractions should be measured?', '["Total and unconjugated bilirubin", "Total bilirubin only", "Total and conjugated bilirubin", "Conjugated bilirubin only"]'::jsonb, 2, 'Measure total AND conjugated (direct) bilirubin. A raised conjugated fraction points to cholestasis or biliary atresia and changes management.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 99, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Indomethacin may reduce polyhydramnios by:', '["Increasing fetal swallowing", "Causing uterine contractions", "Increasing maternal urine output", "Reducing fetal urine production"]'::jsonb, 3, 'It can cause premature closure of the fetal ductus arteriosus, so use is limited.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(2, 100, 'Anaesthesia Nursing Mock — Day 6 Afternoon (Nov 2026)', 'NAP 425 · Anaesthesia for Special Surgery I', 'Urethral catheterisation should not be attempted in pelvic trauma with:', '["Clear urine in the drainage bag", "An associated fractured wrist", "Blood at the urethral meatus", "A normal hourly urine output"]'::jsonb, 2, 'Blood at the meatus suggests urethral injury. A retrograde urethrogram is done first; suprapubic catheterisation may be needed.', 'NAP 425 · Anaesthesia for Special Surgery I'),
(3, 1, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Ultrasound guidance for peripheral nerve blocks mainly improves:', '["The speed of general anaesthesia", "The patient''s fasting status and the timing of the operation list", "Accuracy and safety, with less local anaesthetic needed", "Muscle relaxation for intubation"]'::jsonb, 2, 'Nerves, vessels and the spreading drug can be seen.', 'NAP 432 · General Anaesthesia II'),
(3, 2, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Post-operative wound drain output of 400 mL of fresh blood in the first hour in PACU should be:', '["Ignored, because drains always lose this much in the first hour", "Documented at the end of the shift on the fluid balance chart", "Managed by removing the drain so that the bleeding stops", "Reported immediately to the surgeon as possible active bleeding"]'::jsonb, 3, 'Large or increasing fresh blood loss suggests active bleeding needing surgical review, possible return to theatre, cross-match and resuscitation.', 'NAP 432 · General Anaesthesia II'),
(3, 3, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'An ICU patient is experiencing pain postoperatively. What interventions can the nurse implement to manage the patient''s pain effectively?', '["Encouraging the patient to tough it out", "Limiting the use of pain medications to prevent dependence", "Applying ice packs to the surgical site", "Administering pain medications as needed"]'::jsonb, 3, 'Scheduled or as-needed analgesia, guided by ongoing pain assessment, is the mainstay of effective postoperative pain management.', 'NAP 432 · General Anaesthesia II'),
(3, 4, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A patient in PACU who received a large volume of irrigation fluid during TURP becomes confused with low sodium. This suggests:', '["Normal emergence from anaesthesia", "Hypercalcaemia from immobility after the operation", "TURP syndrome from fluid absorption", "Allergy to the urinary catheter"]'::jsonb, 2, 'Restrict fluids, check sodium and inform the team.', 'NAP 432 · General Anaesthesia II'),
(3, 5, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Inadequate pain control after surgery can lead to:', '["Lower blood pressure and a slower heart rate after surgery", "Shallow breathing, atelectasis and slow mobilisation", "Faster wound healing and a shorter hospital stay", "Better sleep on the first night after surgery"]'::jsonb, 1, 'Good analgesia allows deep breathing and coughing.', 'NAP 432 · General Anaesthesia II'),
(3, 6, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'The maximum recommended dose of bupivacaine is about:', '["2 mg/kg", "0.2 mg/kg", "20 mg/kg", "7 mg/kg with adrenaline"]'::jsonb, 0, 'It is particularly cardiotoxic in overdose.', 'NAP 432 · General Anaesthesia II'),
(3, 7, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A gum elastic bougie is used during intubation to:', '["Guide the tube when the glottis is only partly seen", "Measure the pressure inside the endotracheal tube cuff", "Replace the laryngoscope blade", "Suction secretions from the trachea"]'::jsonb, 0, 'The tube is railroaded over the bougie into the trachea.', 'NAP 432 · General Anaesthesia II'),
(3, 8, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A patient in PACU suddenly becomes hypotensive with wheeze, rash and facial swelling after IV antibiotic. The first drug is:', '["Oral antihistamine only", "IV furosemide 40 mg", "IM adrenaline 0.5 mg", "IV morphine 10 mg"]'::jsonb, 2, 'Stop the antibiotic, give oxygen, fluids and call for help.', 'NAP 432 · General Anaesthesia II'),
(3, 9, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Inspiratory muscle training in a patient who is difficult to wean aims to:', '["Replace the need for ventilator settings", "Increase the patient''s sedation needs", "Reduce cough strength to rest the lungs", "Strengthen the diaphragm and aid weaning"]'::jsonb, 3, 'Threshold devices give resistance to inspiration for set periods.', 'NAP 432 · General Anaesthesia II'),
(3, 10, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A patient in the ICU is experiencing nausea and vomiting. What interventions can help alleviate these symptoms?', '["Placing the patient in Trendelenburg position", "Encouraging the patient to eat a full meal", "Administering anti-emetics", "Limiting oral intake to clear liquids only"]'::jsonb, 2, 'Antiemetics directly target the nausea/vomiting pathway to relieve symptoms.', 'NAP 432 · General Anaesthesia II'),
(3, 11, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A patient is extubated ''awake'' rather than ''deep'' mainly when:', '["The patient is a child with a cold", "The surgeon is in a hurry and the next case is ready to start", "The patient has mild asthma only", "There is a risk of aspiration or a difficult airway"]'::jsonb, 3, 'Awake patients can protect their own airway.', 'NAP 432 · General Anaesthesia II'),
(3, 12, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'FLACC is a pain assessment tool used mainly for:', '["Assessing nausea and vomiting", "Young children and non-verbal patients", "Fully alert adults who can talk", "Measuring sedation depth in ICU patients"]'::jsonb, 1, 'Face, Legs, Activity, Cry, Consolability.', 'NAP 432 · General Anaesthesia II'),
(3, 13, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'The anaesthetic gas scavenging system (AGSS) is used to:', '["Warm and humidify inspired gases", "Measure the end-tidal CO₂ and gas concentrations in the circuit", "Recycle oxygen back to the patient", "Remove waste anaesthetic gases and protect theatre staff"]'::jsonb, 3, 'Long-term exposure to waste gases may harm staff.', 'NAP 432 · General Anaesthesia II'),
(3, 14, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A post-operative patient with high-flow suction on a nasogastric tube in PACU should be monitored for:', '["Fluid and electrolyte losses, mainly potassium", "Polycythaemia caused by the suction pump", "Rapid weight gain from fluid retention in the abdominal wall", "Hyperglycaemia only, from the stress response"]'::jsonb, 0, 'Record NG output on the fluid chart.', 'NAP 432 · General Anaesthesia II'),
(3, 15, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Minimum alveolar concentration (MAC) of an inhalational agent is a measure of its:', '["Toxicity", "Duration", "Cost", "Potency"]'::jsonb, 3, 'MAC is the alveolar concentration that prevents movement in 50% of subjects to a surgical stimulus. A lower MAC means a more potent agent.', 'NAP 432 · General Anaesthesia II'),
(3, 16, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'An advantage of nasotracheal intubation is:', '["Lower infection risk", "Less mucosal damage and bleeding", "Greater tube movement", "Easier oral hygiene"]'::jsonb, 3, 'A nasal tube leaves the mouth free for oral hygiene and is better tolerated and more stable long term. It carries risks of epistaxis and sinusitis.', 'NAP 432 · General Anaesthesia II'),
(3, 17, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A patient in PACU who is shivering should first receive:', '["Oxygen and active warming", "Removal of all blankets", "IV potassium chloride given rapidly", "Cold IV fluids"]'::jsonb, 0, 'Shivering raises oxygen demand greatly.', 'NAP 432 · General Anaesthesia II'),
(3, 18, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'The most common causes of anaphylaxis during anaesthesia are:', '["Sterile water and lubricants", "Neuromuscular blockers, antibiotics and chlorhexidine", "Oxygen and nitrous oxide from the anaesthetic machine", "Normal saline and dextrose"]'::jsonb, 1, 'Treat with adrenaline, fluids, oxygen and stop the trigger.', 'NAP 432 · General Anaesthesia II'),
(3, 19, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'The modified Aldrete score assesses activity, respiration, circulation, consciousness and:', '["Pain score on a 0–10 scale", "Oxygen saturation", "Urine output", "Blood glucose"]'::jsonb, 1, 'A score of 9 or more out of 10 usually allows discharge to the ward.', 'NAP 432 · General Anaesthesia II'),
(3, 20, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A post-operative COPD patient who retains CO₂ should have oxygen titrated to:', '["SpO₂ 70–75%", "SpO₂ 100% at all times", "SpO₂ 88–92%", "No oxygen at all"]'::jsonb, 2, 'Too much oxygen can worsen hypercapnia.', 'NAP 432 · General Anaesthesia II'),
(3, 21, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'After intubation, breath sounds are heard only on the right side. The likely cause is:', '["Endobronchial (right main bronchus) intubation", "Left tension pneumothorax only", "Normal finding after intubation", "Oesophageal intubation with gas entering the stomach"]'::jsonb, 0, 'Withdraw the tube slightly while listening, then re-secure.', 'NAP 432 · General Anaesthesia II'),
(3, 22, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A postoperative ICU patient is at risk for developing urinary retention. What nursing interventions can help prevent urinary retention?', '["Limiting fluid intake", "Encouraging ambulation", "Providing a bedside commode", "Inserting a catheter"]'::jsonb, 1, 'Ambulation promotes normal bladder emptying and reduces urinary retention risk in postoperative ICU patients.', 'NAP 432 · General Anaesthesia II'),
(3, 23, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A patient in the postoperative period experiences delayed wound healing. Which factor should be assessed to determine the cause?', '["Blood glucose levels", "White blood cell count", "Respiratory rate", "Blood pressure"]'::jsonb, 0, 'Elevated blood glucose impairs wound healing, so glycaemic control is assessed as a contributing factor to delayed healing.', 'NAP 432 · General Anaesthesia II'),
(3, 24, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'In a circle breathing system, soda lime is used to:', '["Humidify the fresh oxygen supply to the patient", "Filter bacteria and viruses from the exhaled air", "Remove anaesthetic vapour before it is rebreathed", "Absorb exhaled CO₂ so gases can be rebreathed"]'::jsonb, 3, 'Soda lime reacts with CO2, producing heat and water. Exhausted soda lime changes colour (indicator) and must be replaced, or CO2 rebreathing occurs.', 'NAP 432 · General Anaesthesia II'),
(3, 25, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Nasal airway is not indicated in one of the following', '["Pediatric patient", "Full conscious patient", "Comatose patient", "Basal skull fracture"]'::jsonb, 3, 'A nasal airway risks intracranial passage and is avoided in suspected basal skull fracture, particularly with signs like CSF rhinorrhoea or panda eyes.', 'NAP 432 · General Anaesthesia II'),
(3, 26, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'The Apfel score for PONV includes female sex, non-smoker, history of PONV or motion sickness and:', '["Postoperative opioid use", "Use of local anaesthetic", "Blood group O", "Age over 80"]'::jsonb, 0, 'Each factor raises the risk by about 20%.', 'NAP 432 · General Anaesthesia II'),
(3, 27, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'The usual endotracheal tube cuff pressure target is:', '["50–60 cmH₂O", "5–10 cmH₂O", "80–100 cmH₂O", "20–30 cmH₂O"]'::jsonb, 3, 'Higher pressure causes tracheal mucosal ischaemia; lower risks aspiration.', 'NAP 432 · General Anaesthesia II'),
(3, 28, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Which anaesthetic agent does NOT trigger malignant hyperthermia?', '["Halothane", "Thiopentone", "Suxamethonium", "Isoflurane"]'::jsonb, 1, 'Volatile agents (halothane, isoflurane) and suxamethonium trigger malignant hyperthermia. IV agents like thiopentone and propofol are safe.', 'NAP 432 · General Anaesthesia II'),
(3, 29, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Regional anaesthesia is contraindicated in', '["Eclampsia", "Abrutio placenta", "Diagnosis of placenta previa", "Thrombocytopenia and elevated bleeding time"]'::jsonb, 0, 'Eclampsia with coagulopathy or haemodynamic instability is a contraindication to neuraxial techniques; regional anaesthesia is otherwise often preferred in obstetrics.', 'NAP 432 · General Anaesthesia II'),
(3, 30, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Following surgery, a patient develops signs of seroma formation. Which intervention is appropriate for managing this complication?', '["Drainage of the fluid through a needle", "Applying heat packs to the area", "Manual compression to the affected site", "Encouraging increased fluid intake"]'::jsonb, 0, 'Needle drainage removes the accumulated fluid and relieves a symptomatic seroma.', 'NAP 432 · General Anaesthesia II'),
(3, 31, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A patient is at risk for developing deep vein thrombosis (DVT) following surgery. What nursing interventions can help prevent DVT in the post-operative period?', '["Apply compression stockings as ordered", "Keep the patient well-hydrated to prevent blood clots", "Encourage the patient to remain sedentary and avoid moving around", "Elevate the patient''s legs above heart level at all times"]'::jsonb, 0, 'Graduated compression stockings promote venous return and reduce DVT risk in postoperative patients.', 'NAP 432 · General Anaesthesia II'),
(3, 32, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'The ''LEMON'' airway assessment includes Look, Evaluate 3-3-2, Mallampati, Obstruction and:', '["Nil by mouth status", "Number of teeth", "Nasal patency", "Neck mobility"]'::jsonb, 3, 'Each item flags a possible difficult airway.', 'NAP 432 · General Anaesthesia II'),
(3, 33, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A patient in the ICU develops signs of hypovolemic shock postoperatively. What interventions should the nurse prioritize?', '["Administering vasopressors", "Increasing IV fluid rate", "Elevating the legs", "Monitoring vital signs closely"]'::jsonb, 1, 'Increasing IV fluid administration restores circulating volume in hypovolaemic shock.', 'NAP 432 · General Anaesthesia II'),
(3, 34, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'Pencil-point (e.g. Whitacre) spinal needles are preferred because they:', '["Allow an epidural catheter to pass", "Inject the local anaesthetic faster and with less resistance", "Are easier to see on X-ray", "Reduce the risk of post-dural puncture headache"]'::jsonb, 3, 'They part the dural fibres instead of cutting them.', 'NAP 432 · General Anaesthesia II'),
(3, 35, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 432 · General Anaesthesia II', 'A patient''s urine output in PACU is 10 mL/h for 2 hours after major surgery (70 kg). The nurse should:', '["Remove the catheter and wait for the patient to void", "Do nothing, as this output is normal after major surgery", "Check the catheter, assess fluid status and inform the doctor", "Give a diuretic straight away to increase the output, without assessment"]'::jsonb, 2, 'Target is at least 0.5 mL/kg/h (35 mL/h here).', 'NAP 432 · General Anaesthesia II'),
(3, 36, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Humidification is important for tracheostomy patients because:', '["The nose and upper airway that warm and moisten air are bypassed", "It is not important, because the trachea moistens the air by itself", "Humidified air increases the risk of chest infection in these patients", "Humidification makes secretions thicker and so easier to suction out"]'::jsonb, 0, 'Dry air thickens secretions and may block the tube.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 37, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A nurse is providing care for a newborn who is at risk for hypothermia. The most effective nursing intervention is to:', '["Keep the newborn''s crib away from any heat sources", "Bathe the newborn immediately after birth", "Wrap the newborn in a cold towel", "Place the newborn under a radiant warmer"]'::jsonb, 3, 'Placing the newborn under a radiant warmer is the most effective way to prevent and treat hypothermia. It provides a constant source of heat that helps to maintain the newborn''s body temperature. Bathing should be delayed until the temperature is stable.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 38, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Blue colour, Moderate tone, Inadequate breath and Slow heart rate in a neonate should be followed by which action', '["Keep baby in the cot", "Commence breastfeeding", "Wrap baby and handover to mother", "Commence active resuscitation"]'::jsonb, 3, 'Blue colour, poor tone, inadequate breathing, and slow heart rate mean the neonate needs active resuscitation.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 39, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Immediately after the insertion of a chest tube, vital signs should be monitored at what rate?', '["15 minutes for 4 hours", "15 minutes for 3 hours", "15 minutes for 2 hours", "15 minutes for 1 hour"]'::jsonb, 3, 'Vital signs are typically checked every 15 minutes for the first hour after chest tube insertion.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 40, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'The most common cause of skin graft failure is:', '["Haematoma or seroma under the graft", "Too much immobilisation of the graft", "A clean, well-vascularised wound bed", "Using a split-thickness skin graft"]'::jsonb, 0, 'Fluid separates the graft from the bed, preventing revascularisation. Infection and shear are also causes.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 41, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'The commonest cause of trismus after dental extraction or infection is:', '["Hypocalcaemia only, from poor oral intake", "Facial nerve palsy from the dental injection", "Spasm of the chewing muscles from inflammation", "Fracture of the skull base after the extraction"]'::jsonb, 2, 'Trismus can make intubation very difficult; anaesthetists may need fibreoptic intubation.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 42, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'The most common cause of a neck lump in a child is:', '["Thyroid cancer spreading to the neck nodes", "Laryngeal cancer", "Reactive lymph nodes from infection", "Salivary stones"]'::jsonb, 2, 'Persistent, hard or growing lumps need investigation.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 43, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'After thyroid or neck surgery, the throat pack used during ENT surgery should be:', '["Ignored, as it dissolves in the stomach", "Counted and documented as removed", "Left in place", "Removed only the next day"]'::jsonb, 1, 'A retained throat pack causes airway obstruction.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 44, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A neonate with seizures should first have checked:', '["Blood glucose and calcium", "Hearing response to sound", "Visual response to light", "Hip stability on testing"]'::jsonb, 0, 'Hypoglycaemia and hypocalcaemia are common treatable causes.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 45, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A sudden drop in blood pressure with raised CVP and narrow pulse pressure after cardiac surgery suggests:', '["Hypovolaemia only", "Cardiac tamponade", "Normal recovery", "Hypertension"]'::jsonb, 1, 'Urgent surgical review is needed.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 46, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A chemical splash to the eye should first be treated by:', '["Applying a firm eye pad and waiting for the doctor", "Immediate copious irrigation with water or saline", "Using antibiotic ointment only, with no irrigation", "Rubbing the eye gently to remove the chemical"]'::jsonb, 1, 'Alkali burns are especially dangerous. pH is checked after irrigation.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 47, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'The correct first aid for a chemical burn is:', '["Cover with a dry dressing only", "Copious irrigation with water", "Apply ice directly", "Apply a neutralising agent immediately"]'::jsonb, 1, 'Water dilutes and washes away the chemical; neutralisers generate extra heat and worsen the burn.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 48, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'What is the primary purpose of the underwater seal in a UWSD system?', '["To apply negative pressure to the chest cavity", "To measure the amount of fluid drained from the chest", "To prevent air from re-entering the pleural space", "To collect the drainage from the pleural space"]'::jsonb, 2, 'The water seal acts as a one-way valve, allowing air and fluid to exit the chest cavity but preventing air from being sucked back in, which would worsen the pneumothorax.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 49, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A patient in labour has premature rupture of membranes with meconium-stained liquor. This finding is significant because it may indicate:', '["A sign of maternal infection only", "Definite fetal death, requiring no further action", "A completely normal, reassuring finding with no significance", "Possible fetal distress, requiring closer fetal monitoring"]'::jsonb, 3, 'Meconium-stained liquor can indicate fetal distress and requires closer fetal monitoring and preparation for potential neonatal complications at delivery.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 50, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A patient after jaw surgery who is unable to swallow saliva should be:', '["Given suction at the bedside and nursed head-up", "Fed solids", "Laid flat on the back and given solid food to swallow", "Left unattended"]'::jsonb, 0, 'Drooling may occur because of swelling.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 51, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Cervical incompetence is when the cervical tissue is:', '["Thickened by fibroids", "Weak", "Fully closed", "Firm and long"]'::jsonb, 1, 'Cervical incompetence is weakness of the cervical tissue, leading to painless dilatation in the second trimester.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 52, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'The main risk of a maxillary sinus opening after upper molar extraction is:', '["An oro-antral fistula", "Facial palsy", "Hearing loss on that side", "Mandible fracture"]'::jsonb, 0, 'Patients should avoid nose blowing.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 53, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A patient has total burns to the groin, anterior trunk and the the left upper limb. Using the Wallace rules of nine, the TBSAB is?', '["28%", "27%", "36%", "29%"]'::jsonb, 2, 'Groin (1%) + anterior trunk (18%) + left upper limb (9%) = 28%, closest matching answer is A given typical Wallace rule combinations (approximated to 36% if groin counted differently) — select based on standard summation closest to provided options.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 54, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A patient with 40% total body surface area burns is being resuscitated using the Parkland formula. If the patient weighs 70kg, the total fluid requirement for the first 24 hours is calculated as:', '["4 x 40 = 160ml", "4 x 70 x 40 = 11,200ml", "70 x 40 = 2,800ml only", "No formula is used for burns"]'::jsonb, 1, 'The Parkland formula is 4ml x weight(kg) x %TBSA burned = total 24-hour fluid requirement; here 4 x 70 x 40 = 11,200ml, with half given in the first 8 hours.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 55, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'When instilling two different eye drops, the patient should wait about:', '["5 seconds between drops", "5 minutes between drops", "No time at all", "2 hours between drops"]'::jsonb, 1, 'This stops the first drop being washed out.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 56, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Laryngectomy patients breathe through:', '["The mouth, through a voice tube", "A nasal cannula with oxygen", "A permanent stoma in the neck", "The nose, as before surgery"]'::jsonb, 2, 'There is no connection between the mouth and the trachea. Oxygen and resuscitation must be given via the stoma.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 57, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A patient with circumferential full-thickness burns to the chest has difficulty breathing. The nurse anticipates:', '["Bronchoscopy", "Fasciotomy", "Escharotomy", "Chest tube insertion"]'::jsonb, 2, 'Circumferential eschar restricts chest expansion; escharotomy relieves pressure.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 58, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Trachoma control follows the SAFE strategy: Surgery, Antibiotics, Facial cleanliness and:', '["Early cataract surgery", "Eye patching for all children at night", "Environmental improvement", "Electric light"]'::jsonb, 2, 'Azithromycin mass treatment is used.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 59, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Cushing''s triad of rising intracranial pressure is:', '["Tachycardia, hypertension and diarrhoea with flushing and sweating", "Hypotension, bradycardia and polyuria with dilute urine and thirst", "Hypertension with wide pulse pressure, bradycardia and irregular breathing", "Hypotension, tachycardia and fever with a rapid, shallow breathing pattern"]'::jsonb, 2, 'It is a late sign indicating imminent brain herniation and requires urgent intervention.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 60, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Tropicamide drops are used before eye examination to:', '["Treat infection", "Lower eye pressure", "Dilate the pupil", "Constrict the pupil"]'::jsonb, 2, 'Patients should not drive until vision returns to normal.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 61, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'An artificial eye (prosthesis) socket should be:', '["Never cleaned, so the socket is not disturbed", "Cleaned regularly and checked for discharge", "Rinsed with alcohol", "Kept dry and uncovered"]'::jsonb, 1, 'Teach the patient how to remove and insert the prosthesis.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 62, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'After total laryngectomy, the patient cannot:', '["Smell anything ever, even with help", "Breathe through the nose or mouth", "Swallow at all", "Hear"]'::jsonb, 1, 'The trachea is brought out as a permanent stoma.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 63, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A subdural hematoma most commonly results from tearing of which structure?', '["Middle meningeal artery", "Basilar artery", "Anterior cerebral artery", "Bridging veins"]'::jsonb, 3, 'Subdural hematomas arise from venous bleeding, typically from tearing of the bridging veins that traverse the subdural space between the brain surface and dura.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 64, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Temporomandibular joint (TMJ) dislocation presents with:', '["Double vision", "Loss of hearing", "Inability to close the mouth", "Inability to open the mouth at all"]'::jsonb, 2, 'Reduction is done by pushing the mandible down and back.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 65, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Post-tonsillectomy, a child who swallows frequently while asleep may be:', '["Comfortable and sleeping well", "Dehydrated only", "Bleeding from the tonsil bed", "Hungry"]'::jsonb, 2, 'Frequent swallowing, rising pulse and pallor indicate haemorrhage. Primary haemorrhage occurs within 24 hours; secondary at 5-10 days from infection.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 66, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'After parotidectomy, the nerve most at risk of injury is the:', '["Vagus nerve", "Facial nerve", "Trigeminal nerve", "Hypoglossal nerve"]'::jsonb, 1, 'The facial nerve passes through the parotid gland. Facial weakness should be assessed post-operatively.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 67, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Cleft palate surgery mainly aims to:', '["Improve speech, feeding and hearing", "Improve vision and eye movement", "Correct an associated inguinal hernia", "Treat a fracture of the upper jaw"]'::jsonb, 0, 'A multidisciplinary team includes speech therapists, orthodontists and ENT.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 68, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'Persistent hoarseness for more than 3 weeks in a smoker should be investigated to exclude:', '["Laryngeal cancer", "Ear wax blocking the ear canal", "Common cold", "Tonsillitis"]'::jsonb, 0, 'Refer for laryngoscopy.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 69, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'The positioning concern in neurosurgery performed in the sitting position is:', '["Venous air embolism", "Aortocaval compression", "Lithotomy nerve injury", "Hip dislocation"]'::jsonb, 0, 'Veins above heart level have negative pressure and can entrain air. Monitoring end-tidal CO2 and Doppler helps detection.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 70, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 433 · Anaesthesia for Special Surgery II', 'A ventriculo-peritoneal (VP) shunt is used to treat:', '["Stroke", "Brain abscess", "Hydrocephalus", "Migraine"]'::jsonb, 2, 'Shunt blockage presents with headache, vomiting, drowsiness and in infants a bulging fontanelle.', 'NAP 433 · Anaesthesia for Special Surgery II'),
(3, 71, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Once-daily dosing of gentamicin is used because aminoglycosides:', '["Are best given as a continuous infusion", "Kill bacteria in a time-dependent way only", "Kill bacteria in a concentration-dependent way", "Are not toxic to the kidney or ear"]'::jsonb, 2, 'High peaks kill bacteria, and low troughs reduce nephrotoxicity and ototoxicity.', 'NAP 431 · Applied Pharmacology III'),
(3, 72, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'A drug is available as a 1:10,000 solution, commonly used for cardiac arrest adrenaline. How many milligrams are in a 10 mL prefilled syringe of this solution?', '["0.1 mg", "100 mg", "10 mg", "1 mg"]'::jsonb, 3, 'A 1:10,000 solution = 1 g in 10,000 mL = 0.1 mg/mL. 10 mL x 0.1 mg/mL = 1 mg, the standard cardiac arrest dose.', 'NAP 431 · Applied Pharmacology III'),
(3, 73, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Metoclopramide is avoided in bowel obstruction because it:', '["Is an opioid", "Increases gut motility", "Raises blood pressure", "Causes constipation"]'::jsonb, 1, 'It is a dopamine antagonist with prokinetic action.', 'NAP 431 · Applied Pharmacology III'),
(3, 74, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Digoxin toxicity is suggested by:', '["Increased appetite and better sleep", "Nausea, yellow vision, bradycardia and arrhythmias", "Tachycardia with high blood pressure only", "Weight gain and ankle swelling alone"]'::jsonb, 1, 'Hypokalaemia increases the risk of digoxin toxicity. The apical pulse is checked before each dose; it is withheld if below 60 per minute unless directed.', 'NAP 431 · Applied Pharmacology III'),
(3, 75, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Metformin is usually withheld before surgery with iodinated contrast or major surgery because of the risk of:', '["Hypoglycaemia", "Hyperkalaemia", "Lactic acidosis", "Hypertension"]'::jsonb, 2, 'Restart when kidney function and eating are normal.', 'NAP 431 · Applied Pharmacology III'),
(3, 76, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Propofol infusion syndrome is a rare but serious complication associated with:', '["Prolonged, high-dose propofol infusion", "Fentanyl use", "Dexmedetomidine use", "Short-term, low-dose propofol use"]'::jsonb, 0, 'Propofol infusion syndrome, involving metabolic acidosis, rhabdomyolysis, and cardiac failure, is associated with prolonged high-dose propofol infusions, particularly in critically ill patients.', 'NAP 431 · Applied Pharmacology III'),
(3, 77, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Dexmedetomidine is useful in ICU because it:', '["Sedates with little respiratory depression", "Has no effect on heart rate", "Is a long-acting opioid analgesic", "Causes deep amnesia and apnoea"]'::jsonb, 0, 'It is an alpha-2 agonist. Side effects include bradycardia and hypotension.', 'NAP 431 · Applied Pharmacology III'),
(3, 78, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'The specific reversal agent for unfractionated heparin is:', '["Vitamin K", "Protamine sulfate", "Dantrolene", "Fresh frozen plasma only"]'::jsonb, 1, 'Protamine sulfate binds and neutralises heparin, providing rapid reversal of its anticoagulant effect.', 'NAP 431 · Applied Pharmacology III'),
(3, 79, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'A patient on fentanyl PCA has a respiratory rate of 8/min and is somnolent. Which antidote should the nurse administer?', '["Flumazenil", "Romazicon", "Naloxone", "Physostigmine"]'::jsonb, 2, 'Naloxone reverses opioid-induced respiratory depression. Flumazenil reverses benzodiazepines.', 'NAP 431 · Applied Pharmacology III'),
(3, 80, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'A patient receiving IV heparin has an aPTT of 110 seconds. Which reversal agent should be available?', '["Protamine sulfate", "Andexanet alfa", "Idarucizumab", "Vitamin K"]'::jsonb, 0, 'Protamine sulfate reverses heparin. Vitamin K is for warfarin; idarucizumab/andexanet for DOACs.', 'NAP 431 · Applied Pharmacology III'),
(3, 81, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'A patient is receiving a sedative with a continuous infusion. The nurse notes that the patient''s respiratory rate is 8 breaths per minute. The most appropriate action is to:', '["Stop the sedative infusion and administer Naloxone", "Increase the sedative infusion rate", "Continue to monitor the patient closely", "Stop the sedative infusion and stimulate the patient"]'::jsonb, 3, 'A respiratory rate of 8 breaths per minute is a sign of severe respiratory depression. The nurse should immediately stop the sedative infusion and stimulate the patient to encourage them to breathe. Naloxone is for opioid overdose, and the nurse should not increase the infusion rate.', 'NAP 431 · Applied Pharmacology III'),
(3, 82, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'A patient with opioid overdose has respiratory depression. Naloxone is administered but wears off in 30 minutes. Which action is BEST?', '["Switch to naltrexone", "Start flumazenil", "Intubate the patient", "Give a second naloxone dose"]'::jsonb, 3, 'Naloxone has a short half-life; redosing is needed for long-acting opioids (e.g., methadone).', 'NAP 431 · Applied Pharmacology III'),
(3, 83, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Warfarin before elective surgery is usually stopped about:', '["On the morning of surgery", "1 month before", "5 days before, with INR checked the day before", "6 hours before"]'::jsonb, 2, 'High-risk patients may need bridging with heparin.', 'NAP 431 · Applied Pharmacology III'),
(3, 84, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'A patient receiving IV insulin for hyperglycemia should be monitored for:', '["Hypocalcemia", "Hypermagnesemia", "Hypokalemia", "Hypernatremia"]'::jsonb, 2, 'Insulin shifts K⁺ intracellularly, causing hypokalemia.', 'NAP 431 · Applied Pharmacology III'),
(3, 85, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'A nurse is managing the pain of a patient who is sedated. The nurse knows that the most effective way to assess a sedated patient''s pain is by:', '["Using a behavioral pain scale, such as the BPS or CPOT", "Assessing the patient''s heart rate and blood pressure", "Assuming the patient is not in pain since they are sedated", "Asking the patient to rate their pain on a scale of 1-10"]'::jsonb, 0, 'A sedated patient cannot verbally communicate their pain. The nurse must use a validated behavioral pain scale, such as the Behavioral Pain Scale (BPS) or the Critical-Care Pain Observation Tool (CPOT), which assesses non-verbal signs of pain like facial expressions and body movements.', 'NAP 431 · Applied Pharmacology III'),
(3, 86, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'The relationship between drug concentration and time is studied in:', '["Pharmacovigilance", "Pharmacogenomics", "Pharmacokinetics", "Pharmacodynamics"]'::jsonb, 2, 'Pharmacokinetics is what the body does to the drug (absorption, distribution, metabolism, excretion), i.e. drug concentration over time.', 'NAP 431 · Applied Pharmacology III'),
(3, 87, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'A patient on warfarin has an INR of 8.0. Which reversal agent is used for active bleeding?', '["Vitamin K IV", "Protamine sulfate", "FFP", "Andexanet alfa"]'::jsonb, 2, 'FFP provides immediate clotting factors for warfarin reversal. Vitamin K works slowly.', 'NAP 431 · Applied Pharmacology III'),
(3, 88, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Calcium gluconate is given intravenously in hyperkalaemia to:', '["Correct the metabolic acidosis that causes hyperkalaemia", "Lower the serum potassium level directly and quickly", "Increase urine output so potassium is excreted faster", "Stabilise the myocardium and protect against arrhythmias"]'::jsonb, 3, 'Calcium protects the heart but does not reduce potassium. Insulin with glucose and salbutamol shift potassium into cells; resins or dialysis remove it.', 'NAP 431 · Applied Pharmacology III'),
(3, 89, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'Flumazenil is used to reverse:', '["Benzodiazepine sedation", "Neuromuscular blockade", "Heparin anticoagulation", "Opioid overdose"]'::jsonb, 0, 'Flumazenil is a benzodiazepine antagonist. It may precipitate seizures in patients on long-term benzodiazepines or with tricyclic overdose.', 'NAP 431 · Applied Pharmacology III'),
(3, 90, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'NAP 431 · Applied Pharmacology III', 'The oxygen flush valve on an anaesthesia machine delivers pure oxygen directly to the common gas outlet, bypassing the vaporizer, at a flow rate of approximately:', '["100-150 L/min", "35-75 L/min", "1-2 L/min", "5-10 L/min"]'::jsonb, 1, 'The oxygen flush valve delivers oxygen at roughly 35-75 L/min directly from the oxygen supply, bypassing the vaporizers, and should never be activated while the patient is connected to the circuit under positive pressure to avoid barotrauma.', 'NAP 431 · Applied Pharmacology III'),
(3, 91, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'The abbreviation FIFO in store management means:', '["Fast Inventory Follow-up Operation", "First Into Final Order", "Final Item First Out", "First In, First Out"]'::jsonb, 3, 'FIFO stands for First In, First Out, a stock rotation method.', 'GST 420 · Principles of Management & Teaching'),
(3, 92, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'An ICU team designs a new sedation-weaning protocol, trials it on one shift for a week, then reviews compliance and outcome data before deciding whether to adopt it unit-wide. This is an example of:', '["A retrospective nursing audit", "A root cause analysis of an incident", "A risk financing strategy", "A PDSA quality improvement cycle"]'::jsonb, 3, 'Small-scale trial, data review, and decision on wider adoption is the hallmark of the Plan-Do-Study-Act improvement cycle.', 'GST 420 · Principles of Management & Teaching'),
(3, 93, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'A nurse documents care after the patient''s death that was not actually given. This is:', '["Good documentation practice in ICU", "Falsification of records and misconduct", "Acceptable if the care had been planned", "Required by law to complete the chart"]'::jsonb, 1, 'Late entries must be clearly dated and labelled as such.', 'GST 420 · Principles of Management & Teaching'),
(3, 94, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'Justice in ICU resource allocation means:', '["Admitting only patients who can pay in advance", "Admitting friends and relatives of staff first", "First come, first served, whatever the need", "Allocating beds by need and likely benefit"]'::jsonb, 3, 'Triage policies support fair allocation.', 'GST 420 · Principles of Management & Teaching'),
(3, 95, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'Transformational leadership in ICU is characterised by:', '["Leaving staff to make all decisions on their own", "Inspiring a shared vision and encouraging growth", "Strict rules with punishment for every mistake", "Focusing only on tasks, targets and rewards"]'::jsonb, 1, 'It improves staff satisfaction and patient outcomes.', 'GST 420 · Principles of Management & Teaching'),
(3, 96, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'The recommended nurse-to-patient ratio for a ventilated Level 3 patient is:', '["1:6", "1:1", "1:4", "1:2"]'::jsonb, 1, 'Level 2 patients usually need 1:2 nursing.', 'GST 420 · Principles of Management & Teaching'),
(3, 97, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'Which document should be reviewed FIRST during a nursing quality audit?', '["Payroll register", "Hospital inventory", "Staff attendance book", "Patient care records"]'::jsonb, 3, 'Patient care records are the primary source document reviewed first in a nursing quality audit.', 'GST 420 · Principles of Management & Teaching'),
(3, 98, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'A wife shouts at the ICU nurse that her husband is ''not being cared for''. This is most likely:', '["Normal behaviour that needs no response from staff", "An expression of fear and helplessness under stress", "Evidence of a mental illness needing a psychiatrist", "A clear sign that she intends to sue the hospital"]'::jsonb, 1, 'Acknowledge her feelings, listen and provide information calmly.', 'GST 420 · Principles of Management & Teaching'),
(3, 99, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'ICU diaries written by nurses and families help patients by:', '["Filling memory gaps and reducing PTSD", "Replacing the official medical record", "Increasing the ICU length of stay", "Recording drug doses for legal purposes"]'::jsonb, 0, 'They are given to patients after discharge.', 'GST 420 · Principles of Management & Teaching'),
(3, 100, 'Anaesthesia Nursing Mock — Day 6 Night (Nov 2026)', 'GST 420 · Principles of Management & Teaching', 'Felony-related cases in ICU (e.g. gunshot wounds) require the nurse to:', '["Give care and notify police as the law requires", "Discharge the patient quickly to avoid trouble", "Investigate the crime personally at the bedside", "Refuse to treat the patient until police arrive"]'::jsonb, 0, 'Treatment comes first; evidence is handled properly.', 'GST 420 · Principles of Management & Teaching');
